/* 2025年6月30日 文教委員会 会議録全文（正式会議録／公式会議録の転載）。scripts/minutes_fulltext.py で生成。 */
window.SHINAGAWA_DB.registerMinutes({"id":"r07-20250630-9","dateIso":"2025-06-30","title":"2025年6月30日 文教委員会","sourceType":"formal","sourceUrl":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7095#one","fetchedAt":"2026-08-14","characters":54517,"voices":[{"i":1,"speaker":"つる委員長","text":"○午前１０時００分開会\nただいまから文教委員会を開会いたします。\n本日は、お手元の審査・調査予定表のとおり、議案審査、請願・陳情審査、報告事項およびその他を予定しております。\nなお、学務課長、教育総合支援センター長、保育入園調整課長および保育施設運営課長は議案審査のため冒頭から総務委員会に出席しております。また、子育て応援課長は総務委員会でも議案審査が控えるため、途中でご退席いただきます。\nそれでは、本日は審査の都合上、審査・調査予定表の順番を入れ替えて進めてまいります。\n本日も効率的な委員会運営にご協力をよろしくお願いいたします。\nなお、筒井ようすけ副委員長は諸般の事情で遅参するという報告が事務局にありましたので、申し述べておきます。\n本日は、１名の傍聴申請がございますので、ご案内いたします。\n────────────────────────────────────────────\n１ 議案審査\n(8) 第８５号議案 学校教育職員の勤務時間、休日、休暇等に関する条例の一部を改正する条例\n(10) 第８７号議案 幼稚園教育職員の勤務時間、休日、休暇等に関する条例の一部を改正する条例"},{"i":2,"speaker":"つる委員長","text":"それでは、予定表１の議案審査を行います。\n初めに、(8)第８５号議案、学校教育職員の勤務時間、休日、休暇等に関する条例の一部を改正する条例、(10)第８７号議案、幼稚園教育職員の勤務時間、休日、休暇等に関する条例の一部を改正する条例の２議案を議題に供します。\nこれらの議案につきましては、関連する内容のため、一括して説明、質疑を行い、その後、議案ごとに採決を行いたいと思いますので、よろしくお願いいたします。\n本件につきまして、理事者よりご説明願います。"},{"i":3,"speaker":"酒川指導課長","text":"それでは、第８５号議案、学校教育職員の勤務時間、休日、休暇等に関する条例の一部を改正する条例、および第８７号議案、幼稚園教育職員の勤務時間、休日、休暇等に関する条例の一部を改正する条例について説明いたします。\n固有教員および幼稚園教員の子育て部分休暇に係る取得形態を見直すほか、子の年齢に応じた柔軟な働き方を実現するための、仕事と育児の両立支援制度の利用に関する意向確認等の措置を定めるため、所要の規定を新設いたします。\n具体的な内容としましては、まず、子育て部分休暇について、従来の取得パターン、これが３０分を単位として１日につき２時間以内で取得するパターン、これに加えまして、１時間を単位として年度ごとに７７時間３０分の範囲内で取得する新たなパターンを追加いたします。こちらのパターンでは、子育て部分休暇により、丸１日の休暇を取ることが可能となります。\n次に、職員が妊娠・出産等について申出をしたとき、および、子が３歳になるまでの適切な時期に仕事と育児の両立支援制度に係る情報提供・意向確認等の措置を所属長に義務づけます。提供する情報については、規則において定める形になりますが、例えば、育児短時間勤務や部分休業といった制度の周知、またその請求方法の案内といったものになります。\n改正の経緯でございますが、令和６年５月に、育児休業、介護休業等育児又は家族介護を行う労働者の福祉に関する法律が改正されたことに伴い、国家公務員の休暇制度との均衡を図るため、条例改正を行います。\n施行期日は、令和７年１０月１日となります。"},{"i":4,"speaker":"つる委員長","text":"説明が終わりました。\n本件に関しまして、ご質疑等がございましたらご発言願います。"},{"i":5,"speaker":"のだて委員","text":"今回の条例改正では、区の固有教員と区立幼稚園教員の方が対象になるということなのか、対象を伺いたいと思います。\n今の実際の品川区内での子育て部分休暇の利用の実態はどうなっているのか伺います。"},{"i":6,"speaker":"酒川指導課長","text":"まず、今回の条例の対象は、区の固有教員、それから幼稚園教員、区費の職員になります。都費の一般の教員については、都の条例で定められております。\n休暇の取得状況について、統計等は今、ご説明申し上げられませんが、十分取得が勧奨されていると捉えております。"},{"i":7,"speaker":"のだて委員","text":"利用人数というのは、この間、いつからか使えるようになってから、ある時点で何人利用したとか、そういったことは分からないのでしょうか。"},{"i":8,"speaker":"酒川指導課長","text":"今回の８５号議案と８７号議案についてでしょうか。"},{"i":9,"speaker":"のだて委員","text":"従来の取得パターンはあったわけですか。"},{"i":10,"speaker":"酒川指導課長","text":"利用人数の変遷等々については、今、統計を持ち合わせておりません。"},{"i":11,"speaker":"のだて委員","text":"今、利用数が分からないということなので、ぜひ、この制度ができたわけなので、利用していただきたいと思いますし、また、新たにこの取得パターンができるということで、今後、区としては、この利用が進む想定なのか、進めていきたいという思いもあるのかというところで伺いたいと思います。"},{"i":12,"speaker":"酒川指導課長","text":"先ほど説明したところで少し分かりにくかったかもしれませんが、これまでは３０分を単位として１日に２時間以内ということで、１日に２時間という上限があったわけですけれども、この上限を年間７７時間３０分の範囲で取れるということで、例えば３時間取りたいや６時間取りたいといった柔軟な休暇の取得が可能になりますので、これはぜひ子育て支援の制度として進めていきたいと思っております。"},{"i":13,"speaker":"つる委員長","text":"ほかにございますか。"},{"i":14,"speaker":"まつざわ委員","text":"大変すばらしい制度で、いいと思うのですけれども、こういう制度でよくあるのが、要は使いづらいとか、育休が取りづらいという課題はすごく大きいと思うのです。だから、その部分に関して、例えば職員のマニュアルといいますか、こういうのを取っていいのですよ、どんどん取りましょうとか、そういったマニュアルを配布して、こういう部分休暇を取りやすいようにするべきではないかと思うのですけれども、今何かやっていることはありますか。"},{"i":15,"speaker":"酒川指導課長","text":"そういった情報提供、マニュアルですとかは、通知をしているところでございます。広報等々を通して広く全職員に周知するということをやっております。\n今回の条例では、そういったことを周知することが所属長に義務づけられたということで、今まで以上に周知が図られると捉えております。"},{"i":16,"speaker":"つる委員長","text":"ほかにございますか。"},{"i":17,"speaker":"横山委員","text":"１点確認だけなのですけれども、令和７年度の３８時間４５分というのは、１０月からスタートということで、その分短くなっているということで大丈夫でしょうか。"},{"i":18,"speaker":"酒川指導課長","text":"そのとおりでございます。"},{"i":19,"speaker":"つる委員長","text":"ほかにございますか。"},{"i":20,"speaker":"高橋（し）委員","text":"改正の概要の２番目・３番目のところに、先ほどお話ありましたけれども、管理職が意向等を配慮とかを義務づけるとありますが、これは都費の先生も一緒だと思うのですけれども、義務づけるということは、どうしますか、取りますかという話をしたときに、何か書類というか、残すものが、現在もやっているとすると、そういうのがあって、それできちんと教職員から聞きましたというのが後に残るようなものがあるのでしょうか。"},{"i":21,"speaker":"酒川指導課長","text":"そういった書類での約束の取り交わしというのは想定しておりませんで、まずはそういった申告があった教員に対して、こういう制度がありますという紹介をして、どうしましょうかという意向確認をした上で、その後は当該職員がそういった紹介に基づく制度の申請をするということで、保障されていると捉えております。"},{"i":22,"speaker":"高橋（し）委員","text":"確認を義務づけるとあるので、聞きましたと話を管理職の方が言っただけでは、別に言った、言わないで云々という意味ではなくて、このように確認しました、そうしたら教職員が取りたいと言いました、それで取りましたという流れみたいなものは、年休とかを取るのはきちんと書類が出たりするのですけれども、ここに義務づけるとわざわざ書いてあるところが、それはきちんと何らかの形で残したほうがいいのではないかと思うのですが、その辺はどうでしょうか。"},{"i":23,"speaker":"酒川指導課長","text":"現在そういった確認を行いましたということを確認するといいましょうか、立証するというか、そういった書類等々はないわけでございますけれども、管理職へは確実にこれを周知し、意向確認を行うように改めて伝えていきたいと思っております。"},{"i":24,"speaker":"高橋（し）委員","text":"情報提供はしていただくというのは、先ほどほかの委員からもお答えいただいたのですけれども、そこのところは何らかの形式というか、方式を整えていただいたほうがいいと思います。これは要望で、終わります。"},{"i":25,"speaker":"つる委員長","text":"ほかに。"},{"i":26,"speaker":"若林委員","text":"今の高橋しんじ委員のお話も、ごもっともなお話だなと。この場合、校長先生の責務というのでしょうか、義務づけに対する役割というのはどういうものなのですか。"},{"i":27,"speaker":"酒川指導課長","text":"本来は、これは教育委員会が周知の責任を負っております。それを直属の現場の所属長である校長が代行するという形で、申請は教育委員会が受け取るという形になっております。"},{"i":28,"speaker":"若林委員","text":"最終的には教育委員会が、義務づけについてはしっかりと確認をしていくという、確認という言葉を私は使いますけれども、教育委員会が最終的に確認すると。そして、こういう委員会等で１年間、いろいろな報告の中で私たちのほうから確認した場合に、しっかりと義務づけが徹底されています、そのエビデンスはこういうことですというようなご答弁がいただけるということを確認させていただきたい。"},{"i":29,"speaker":"酒川指導課長","text":"そのようにするものと捉えております。"},{"i":30,"speaker":"つる委員長","text":"ほかにございますか。よろしいですか。\n〔「はい」と呼ぶ者あり〕"},{"i":31,"speaker":"つる委員長","text":"ほかにご質疑がないようですので、これで質疑を終了いたします。\n採決に入ります前に、まず、第８５号議案、学校教育職員の勤務時間、休日、休暇等に関する条例の一部を改正する条例につきまして、各会派の態度を確認いたします。\nそれでは、品川区議会自民党・無所属の会からお願いいたします。"},{"i":32,"speaker":"まつざわ委員","text":"賛成です。"},{"i":33,"speaker":"筒井副委員長","text":"賛成です。"},{"i":34,"speaker":"若林委員","text":"賛成です。"},{"i":35,"speaker":"のだて委員","text":"賛成です。"},{"i":36,"speaker":"高橋（し）委員","text":"賛成です。"},{"i":37,"speaker":"横山委員","text":"賛成します。"},{"i":38,"speaker":"つる委員長","text":"それでは、これより第８５号議案、学校教育職員の勤務時間、休日、休暇等に関する条例の一部を改正する条例について、採決いたします。\nお諮りいたします。\n本案は、原案のとおり決定することにご異議ありませんか。\n〔「異議なし」と呼ぶ者あり〕"},{"i":39,"speaker":"つる委員長","text":"ご異議なしと認めます。よって、本案は全会一致で原案のとおり可決決定いたしました。\n次に、第８７号議案、幼稚園教育職員の勤務時間、休日、休暇等に関する条例の一部を改正する条例につきまして、各会派の態度を確認いたします。\nそれでは、品川区議会自民党・無所属の会からお願いいたします。"},{"i":40,"speaker":"まつざわ委員","text":"賛成です。"},{"i":41,"speaker":"筒井副委員長","text":"賛成です。"},{"i":42,"speaker":"若林委員","text":"賛成です。"},{"i":43,"speaker":"のだて委員","text":"賛成です。"},{"i":44,"speaker":"高橋（し）委員","text":"賛成です。"},{"i":45,"speaker":"横山委員","text":"賛成です。"},{"i":46,"speaker":"つる委員長","text":"それでは、これより第８７号議案、幼稚園教育職員の勤務時間、休日、休暇等に関する条例の一部を改正する条例について、採決いたします。\nお諮りいたします。\n本案は、原案のとおり決定することにご異議ありませんか。\n〔「異議なし」と呼ぶ者あり〕"},{"i":47,"speaker":"つる委員長","text":"ご異議なしと認めます。よって、本案は全会一致で原案のとおり可決決定いたしました。\n────────────────────────────────────────────\n(9) 第８６号議案 学校教育職員の旅費に関する条例の一部を改正する条例"},{"i":48,"speaker":"つる委員長","text":"次に、(9)第８６号議案、学校教育職員の旅費に関する条例の一部を改正する条例を議題に供します。\nそれでは、本件につきまして、理事者よりご説明願います。"},{"i":49,"speaker":"酒川指導課長","text":"電子１４ページからになります。第８６号議案、学校教育職員の旅費に関する条例の一部を改正する条例について説明いたします。\n本条例は、固有教員の旅費について定めているものになります。\n固有教員の旅費の取扱いは、同一の職場に勤務する都費負担教員との均衡を踏まえて決定しており、今回、都費負担教員の旅費制度が改正されたことに伴いまして、固有教員の旅費制度についても見直しを行うものです。\n具体的な内容としましては、まず交通費について、従来どおり鉄道賃・船賃・航空賃を支給しますが、これら以外の移動に要する費用について、種目名を「車賃」から「その他の交通費」に改めます。これによって、例えば生徒引率時にはタクシー代やレンタカーの賃料およびそれに付随する有料道路代や駐車場利用料が支給可能となります。また、鉄道賃については、急行料金および座席指定料金に係る距離制度を廃止します。\n次に、宿泊費等について、従来、宿泊料・食卓料・旅行雑費の３つに分かれていたものを、宿泊に要する費用に充てるための「宿泊費」と、夕食代を含む諸雑費に充てるための「宿泊手当」の２つに整理します。宿泊料については、これまでの宿泊先の区分に応じた定額の支給でしたが、本改正によって、都道府県ごとに設定されている上限を超えない範囲で実費支給が可能となります。修学旅行の引率時等は、現行同様、上限額によらず、宿泊に要する額の支給を可能とします。宿泊手当については、夕朝食代を含む諸雑費を１夜当たりの定額で支給するものです。また、パック旅行に要する費用を支給する旅費として、包括宿泊費を新設し、手続を簡素化します。\n次に、転居費等について、赴任に伴う転居に要する費用に充てるための旅費、簡単に言いますと、転勤した際の引っ越し代について、その名称を「移転料」から「転居費」に、また、赴任に伴う転居に必要な滞在に係る費用に充てるための旅費、こちらも簡単に言いますと、転勤後の住居が決まっていない場合の滞在費用について、その名称を「着後手当」から「着後滞在費」にそれぞれ改めます。着後滞在費については、５日を上限として宿泊費と宿泊手当を支給します。加えて、赴任時にも、家族も一緒に移転する場合の旅費について、職員の配偶者・子等の扶養要件を廃止しまして、これに伴い、種目名を「扶養親族移転料」から「家族移転費」に改めます。\n本条例は公布の日から施行し、令和７年４月１日以降に出発する旅行から適用としております。"},{"i":50,"speaker":"つる委員長","text":"説明が終わりました。\nこれより質疑を行います。ご質疑等がございましたら、ご発言願います。"},{"i":51,"speaker":"のだて委員","text":"まず、確認なのですけれども、都の改正内容と今回の改正内容というのは同じ改正内容になるのかというのと、宿泊費のところで、上限があって、そこまでは実費支給になるということでしたけれども、上限をオーバーするようなことというのはあり得るのか伺いたいと思います。"},{"i":52,"speaker":"酒川指導課長","text":"まず、東京都の条例とは同等の改正となっております。\nそれから、上限オーバーということは、場合によってはあり得ると認識しておりますが、今までは、埼玉・千葉・特別区・横浜・川崎等と、都市部においては１万１,０００円が上限でございました。その他の地域については１万円が上限だったのですが、例えば今回の改正では、埼玉・東京・京都は１万９,０００円まで上限を引き上げますということで、８,０００円アップ、これは近頃の宿泊費の高騰への対応と認識しております。"},{"i":53,"speaker":"のだて委員","text":"宿泊費のところでは上限額が引き上がったということで、今までよりはオーバーする可能性が減ったのかなというのもありますけれども、つまりは教員の負担になってしまうような事態というのがどのくらい起こり得るのか、あまりそういった負担にならないようにしていただきたいと思っているのですが、いかがでしょうかというのと、今回いろいろ名称変更などもありますが、改正したときに、要するに全体として負担が減るのか、それとも増えるのかというところを伺いたいと思います。"},{"i":54,"speaker":"酒川指導課長","text":"私自身の経験を踏まえても、かなりこの上限額の引上げというのは経済的負担が減ると考えておりますし、今回の条例改正全体を通しても、かなり柔軟な移動・宿泊が可能になると捉えております。"},{"i":55,"speaker":"のだて委員","text":"実感も含めて、負担が減るということですので、そうすると、今まで結構、教員の方は、旅費としていろいろ負担をされてきたということなのですか。今までの実態を少し説明いただけたらと思います。"},{"i":56,"speaker":"酒川指導課長","text":"一例になりますけれども、例えば関西地方に出張するといったところで、大阪までは新幹線で移動できました。それから、大阪を起点に南北に１００ｋｍ程度移動するとなったときに、１００ｋｍを超える場合は特急料金が出ます。ただ、１００ｋｍを超えない場合、特急料金は出ません。そこで特急料金を使った場合は自腹になりますというような縛りがございましたが、今回は、合理的な移動をした場合は実費で支給ということで、かなりの負担軽減になると捉えております。"},{"i":57,"speaker":"つる委員長","text":"ほかにございますか。よろしいでしょうか。"},{"i":58,"speaker":"高橋（し）委員","text":"今お話あったように、柔軟な対応になったということで、パックができるというのは、かなり教職員の方にとっては利用しやすい状況と思ったのですが、それはそれとして、改正の概要の（１）の4)のところのレンタカーの賃料等の仕組みを変えるということで、今までタクシーで移動したところをレンタカーになるので、引率の先生方にとっては使い勝手がいい、どこかから行ってまたタクシーとかいうよりも、また料金的にも抑えることができるのでいいのですが、レンタカーを使うということは、教職員の方が運転することになるわけで、それだけ様々な万が一のときの事故が起こる可能性も出てくるので、１つは、もちろん公務によって起こる災害なので、それは補償されるかという確認と、もう１つは、レンタカーを使う際には、運転するというのは相当いろいろなことが起きるので、教育委員会から、レンタカーを使用するときの先生方への認識というか、そこをきちんとしましょうというのをお話するつもりはあるのかどうか。やはり事故が起きやすいと思われますので、その２つ、お願いします。"},{"i":59,"speaker":"酒川指導課長","text":"当然、事故が起こる可能性もありますし、公務災害という部分になりますので、保険等々の補償をしっかりしていくということと、あわせて、レンタカーを使うといった場合は気をつけましょうというのは、これは私どもがあえて言うことではないのかもしれませんけれども、こういった制度改正がありましたので、改めてそういったレンタカーみたいなものが使えるわけですが、公務員として規範意識を持って、気をつけて乗りましょうということは伝えていくべきと思っています。"},{"i":60,"speaker":"つる委員長","text":"ほかにございますか。よろしいですか。\nほかにご発言がないようですので、これで質疑を終了いたします。\n採決に入ります前に、まず、第８６号議案、学校教育職員の旅費に関する条例の一部を改正する条例につきまして、各会派の態度を確認いたします。\nそれでは、品川区議会自民党・無所属の会からお願いいたします。"},{"i":61,"speaker":"まつざわ委員","text":"賛成です。"},{"i":62,"speaker":"筒井副委員長","text":"賛成です。"},{"i":63,"speaker":"若林委員","text":"賛成です。"},{"i":64,"speaker":"のだて委員","text":"教員の負担が減るということで、賛成です。"},{"i":65,"speaker":"高橋（し）委員","text":"賛成です。"},{"i":66,"speaker":"横山委員","text":"賛成です。"},{"i":67,"speaker":"つる委員長","text":"それでは、これより第８６号議案、学校教育職員の旅費に関する条例の一部を改正する条例について、採決いたします。\nお諮りいたします。\n本案は、原案のとおり決定することにご異議ありませんか。\n〔「異議なし」と呼ぶ者あり〕"},{"i":68,"speaker":"つる委員長","text":"ご異議なしと認めます。よって、本案は全会一致で原案のとおり可決決定いたしました。\n────────────────────────────────────────────\n(1) 第７６号議案 品川区給付型大学奨学金条例\n(2) 第７７号議案 品川区給付型大学奨学金運営委員会条例"},{"i":69,"speaker":"つる委員長","text":"次に、(1)第７６号議案、品川区給付型大学奨学金条例、(2)第７７号議案、品川区給付型大学奨学金運営委員会条例の２議案を議題に供します。\nこれらの議案につきましては、関連する内容のため、一括して説明、質疑を行い、その後、議案ごとに採決を行いたいと思いますので、よろしくお願いいたします。\n本件につきまして、理事者よりご説明願います。"},{"i":70,"speaker":"柏木子育て応援課長","text":"それでは、第７６号議案、品川区給付型大学奨学金条例および第７７号議案、品川区給付型大学奨学金運営委員会条例の２議案につきまして、一括して説明いたします。\nそれでは、資料の１ページ目をご覧ください。\n初めに、１、品川区給付型大学奨学金条例でございます。\n（１）背景・目的でございます。保護者等に一定の所得があっても、学費が高額な医学部や理系学部などでは進学を諦めざるを得ない場合があります。そのため、希望する子どもが大学に進学できるよう、所得制限のない給付型大学奨学金を創設し、地域社会に貢献する人材の育成を図るものであります。\n（２）制定内容でございます。本条例の概要でございますけれども、1)にございますように、第１条で本条例の目的を定めております。\n2)でございますが、第２条で給付の要件である居住年数、対象学部、学業成績、地域貢献活動への定期的な参加等を定めております。\n3)でございますが、第３条から第６条で、給付の申請・決定、給付額、給付期間等を定めております。給付の決定に当たっては、運営委員会の審議を経て決定すること、給付額は年額５４万円であること、給付期間は大学の修業年限であることを定めております。給付期間でございますが、通常ですと４年間となりますが、医学・歯学・薬学の学部につきましては６年間の支給となります。\n4)でございますが、第７条から第９条で、連帯保証人、給付の停止または取消しの条件、返還を定めております。連帯保証人ですが、万が一給付の取消しにより返還が生じた場合のために指名するものとなります。\n（３）条例案でございますが、別紙のとおりでございます。\n（４）施行日でございますが、公布の日からでございます。\n（５）スケジュールでございますが、８月から広報等で周知・募集を行い、１０月までに一次審査、１２月までに二次審査、そして、運営委員会を経て２月に奨学生を決定し、３月に給付する予定で現在準備を進めております。\n（６）奨学金予算規模でございますが、概算になりますが、今後の見込みについてお示ししております。\n第７６号議案、品川区給付型大学奨学金条例の説明は以上となります。\n続きまして、資料２ページ目、２、品川区給付型大学奨学金運営委員会条例について説明をいたします。\n（１）目的でございますが、先ほど説明いたしました大学奨学金の給付について適正な運営を図るため、設置するものであります。\n（２）制定内容でございます。本条例の概要ですが、1)にございますように、第２条で運営委員会の所掌事項を定めております。所掌事項につきましては、申請者の選考に関すること、奨学金の返還に関すること、その他区長が必要と認める事項としてございます。\n2)でございますが、第３条から第５条で、組織、委員構成、任期、会長・副会長を定めております。委員構成につきましては、高校生の奨学金、在宅応援資金の運営委員会と同様に、区議会議員、学識経験者、区に勤務する職員を考えております。また、他の自治体も参考にさせていただきましたが、他の自治体も同様の委員構成でありました。なお、学識経験者につきましては、高等学校の校長先生を考えております。\n3)でございますが、第６条から第９条で、定足数、表決、委員会の公開を定めております。委員会の公開につきましては、次の観点から非公開としてございます。\n１つ目でございますが、審議の内容が申請者の経済状況や家庭環境といった機微な情報を扱うため、個人情報の保護が重要と考えているからです。\n２つ目でございますが、申請者の匿名性を守り、不要な注目や偏見を避けるなど、申請者のプライバシー保護も重要と考えているからです。\n３つ目としましては、委員が外部からの圧力や影響を受けずに自由な議論や判断ができるよう、審議の自由度を確保することが重要と考えているからです。\n以上の理由によりまして、委員会は非公開とし、公正かつ効果的な委員会の実施を目指してまいります。\n（３）条例案でございますが、別紙のとおりでございます。\n（４）施行日でございますが、公布の日からでございます。\n第７７号議案、品川区給付型大学奨学金運営委員会条例の説明は以上となります。"},{"i":71,"speaker":"つる委員長","text":"説明が終わりました。\n本件に関しまして、ご質疑等がございましたらご発言願います。"},{"i":72,"speaker":"のだて委員","text":"今回の条例は、目的にもあるとおり、家庭の経済に関係なく学ぶことを支援するものなので、私も給付型奨学金を求めてきた者なので、歓迎したいと思います。\nよりよいものにという思いで質問したいと思うのですけれども、まず確認ですが、今回、申請を見込んでいる人数はどのぐらいなのか、そして対象の学部に、これらに類する学位を授与できる学部ということで書かれているのですが、どういったものが対象になるのか伺います。"},{"i":73,"speaker":"柏木子育て応援課長","text":"１つ目の申請者数の見込みでございますが、約２７０名と見込んでございます。その根拠でございますが、品川区の１８歳の人口、それと東京都の大学進学率、また、今回対象としています対象学部の進学率、それと、奨学金は必ずしも全員が申し込むというわけではございませんので、その人数の約半分ということで、約２７０名と見込んでございます。\n次、その他類する学部の件でございますけれども、学部というのは各大学が定めることになってございますので、単純に医学部ですとか農学部という、ほかの名称を使っているという場合がございますので、こちらのほうに、その他で類するという形での規定をさせていただいております。申請いただいた際には、その学部が指定する学部に該当するのか、きちんと確認した上で申請の受付をしたいと考えてございます。"},{"i":74,"speaker":"のだて委員","text":"学部のところは、理工学部とかというところもあったりします。そういうところは明らかに対象になると思いますけれども、そういうものが対象になるということで、分かりました。\n申請者数のところは２７０名見込んでいるということで、そうすると、１００人分ということになりますので、公正・公平にどう選定するのかというところが重要になってくると思うのですけれども、今回、給付の要件に、学業成績が特に優れているということが書かれていますが、これは成績上位から選定するということになるのか伺いたいと思います。\nそれと、もう１つ要件として、区内地域貢献活動への定期的な参加ということで書いてありますけれども、これはどういったものになるのか伺いたいと思います。"},{"i":75,"speaker":"柏木子育て応援課長","text":"初めに、学業成績順に審査というか、決めていくのかというお話ですが、これはあくまでも申請の際の要件という形でございまして、学業成績順に奨学生を決めるということは考えてはございません。\n続きまして、地域貢献活動はどういうものかでございますが、今後、要綱で定めて、募集要項等に例示をしたいと考えてございます。今想定していますのは、町会・自治会のボランティア活動で地域防災など、あと、青少年育成や環境美化、消防団の活動、社会福祉協議会のボランティア活動、そういうものを想定してございますけれども、今後要綱でもう少し詳しく決めていきたいと考えてございます。"},{"i":76,"speaker":"のだて委員","text":"学業については上位順ではないということだったので、いろいろな子どもたちにチャンスがあると思ったのですけれども、地域貢献活動、いろいろ今、例を挙げていただきましたが、これは定期的に参加をしなければいけないということで、これが医療系の大学はなかなか難しいのではないかと。学業で忙しいと思うのですけれども、そこへの対応といいますか、どうされるのか。\n学業が本分だと思うので、そこをおろそかにして、定期的に参加をしなければいけない、おろそかと言うと言い過ぎかもしれませんけれども、そういうことにもなりかねないという危惧もあるし、参加できなくなってしまう、参加できないと取消しにもなってしまうということになるので、そうしたことがないように、多くの子どもたちに学ぶ機会を保障していただきたいと思うのですけれども、いかがでしょうか。"},{"i":77,"speaker":"柏木子育て応援課長","text":"地域貢献活動の定期的な活動についてでございますけれども、最初に、地域貢献活動の「定期的に」の部分は、ある意味、柔軟には考えていきたいと思ってございますが、まず今回、大学奨学金ですけれども、単に経済的理由等はなく大学とか学部に進学できるというだけではなくて、区が行う以上、地域に将来的に不可欠な人材育成というのも重視してございますので、地域貢献については、多少柔軟には当然考えていきたいと思いますけれども、その部分については重視をしていきたいという考えでございます。今後、要綱等を定める中で、詳細に決めていきたいと思います。\n例としましては、大学によっては１年生のときに、他県のキャンパスに１年間、全寮制で通うという大学もあると聞いてございますので、そうなってくると、その方とかは長期の休みでないと参加できないというのもございますので、その辺はきちんと本人の事情等も鑑みて考えていきたいと思っております。"},{"i":78,"speaker":"のだて委員","text":"今ご紹介いただいたように、他県に行かなければいけないということもあるので、そうでなくても、他県の大学に入学したりすると、全寮制でそこに住むことになったりすると。そういった人も、区内の地域貢献活動に参加をするということなので、また新たなハードルになってしまうのではないかという危惧があるのですけれども、その点はどのようにお考えでしょうか。"},{"i":79,"speaker":"柏木子育て応援課長","text":"他県等の大学の場合は、時間的制約等はございますけれども、先ほど申しましたとおり、地域の将来に不可欠な人材育成というものを重視してございますので、当然、学業が優先にはなると思いますけれども、地域に貢献する活動について、必ず参加していただきたいということでございます。"},{"i":80,"speaker":"のだて委員","text":"柔軟に対応していくということなので、ぜひ柔軟に、学業の妨げにならないような形にしていただきたいと。柔軟な対応、今後運用を見ていきたいと思います。\nそれと、運営委員のメンバーなのですけれども、今回、区議会議員と学識経験者、区の職員ということで、約１０人以内ということなのですが、人数構成はどうなっているのか伺いたいのと、これが公平・公正に選定されるようにしていかなければならないと思うのですけれども、恣意的にならないようにするというのはどのように担保していくのか伺います。"},{"i":81,"speaker":"柏木子育て応援課長","text":"運営委員会の構成人数でございますが、今、想定でございますけれども、区議会議員につきましては２名、学識経験者、説明の中で高等学校の校長先生と申し上げましたが、４名。区の職員が、幹部職員でありますけれども、こちらの４名で、計１０名というのを想定しているところでございます。\n次に、審査が恣意的にならないためにということですけれども、今、高校生の奨学金についても、個人名を伏した形で審査いただいているというのもございますので、そういう形で、名前が分かってというような審議にならないように、その辺は恣意的にならないように配慮してまいります。"},{"i":82,"speaker":"のだて委員","text":"恣意的にならないように個人名を伏せたやり方でやっているということで、そうすると、この間、高校生の奨学金制度では、そうした恣意的な事例というのはないという認識でいいのか、確認させていただきたいのと、あと給付額、今回年額で５４万円ということで、国立大学の授業料を参考に定めていると伺っているのですけれども、東京大学は今年度入学者から１０万円も値上げして、約６４万円になっているということで、今後こうした給付額を引き上げるということは考えていらっしゃるのか伺いたいと思います。"},{"i":83,"speaker":"柏木子育て応援課長","text":"初めに高校生奨学金のほうですけれども、恣意的な事例はございません。\n次に給付額ですけれども、今回給付額につきましては、文部科学省が定めております国立大学の授業料を基本としてございますので、今後、国が授業料等の増額をした場合につきましては、その状況を見ながら、年額について改定することはあり得ると思います。"},{"i":84,"speaker":"のだて委員","text":"できるだけ負担がなくなるように、給付額の引上げも含めて検討していっていただきたいと思います。\n今回、医療系と理工農系に限られているわけですけれども、そこの学部に絞った理由を伺いたいと思います。\nこの中で、短期大学ですとか、大学院、専門学校は除かれているということで、ここを除いた理由を伺いたいと思います。今後はぜひこうしたところも対象拡大をしていっていただきたいと思うのですけれども、いかがでしょうか。"},{"i":85,"speaker":"柏木子育て応援課長","text":"学部を絞ったという部分と、４年制大学にしたというところですけれども、少し重なる部分がございますが、まず、大きな限られた予算を効果的に活用して、地域の将来に不可欠な人材育成を重点にするというところで、４年制大学、あと医療系・理工農系学部に絞ったといいますか、給付の対象としてございます。\n学部のほうなのですけれども、医療系学部につきましては、国の奨学金制度の拡充があったのですが、これは対象外であったということと、あと地方自治体として、将来の医療人材育成に貢献するためでございます。\n次に、理工農系学部ですが、地域の製造業やＩＴ産業の発展に資する面があるため、地方自治体として、地域の産業振興と経済発展に寄与する人材育成に貢献をするためでございます。\n繰り返しになりますけれども、こちら２つの学部に特化することで、限られた予算を効果的に活用し、医療や産業・経済など地域の将来に不可欠な人材育成を重点的に支援するためでございます。\nあと、今後学部を拡大するのかというお問合せでございますけれども、まずはこちらの医療系学部と理工農系学部に特化した事業として実施をしていきたいと考えてございます。ただ、今後、国の制度等を注視しつつ、区民の声を聴きながら、事業内容については検討するものと考えてございます。"},{"i":86,"speaker":"つる委員長","text":"ほかにございますか。"},{"i":87,"speaker":"まつざわ委員","text":"今のお話と少し重なってしまうのですけれども、これからいろいろ対象がある、例えば夜学とか通信大学など、働いても大学に行きたいという意欲があったりするので、今回は対象外ですけれども、いずれそういう方も拡充してほしいだとか、例えば地域貢献という部分だったら、教育分野であったり、ＡＩの分野であったり、いろいろ大学がありますので、そういうのも含めて、いずれは検討していただきたいと思っています。\nそれで、今、区内地域貢献活動、大変すばらしいと思っているのですけれども、それこそ、せっかくそういったものを対象にしてやるのであれば、例えば仮に、せっかくそういうのが集まったときに、年に１回可視化をして、そういった方たちの地域貢献がどういうことをやっていますとか、そういった部分のこういうボランティアはいいですよとか、せっかくならそういった見える化といいますか、何かそういうのをすればいいのにと思うのですけれども、その辺はどうでしょうか。"},{"i":88,"speaker":"柏木子育て応援課長","text":"まず、最初にいただきました夜学ですとか、そういう部分の件ですけれども、今後この事業を実施していきながら、区民の声等も聴きながら、事業内容については検討していきたいと考えてございます。\nそれと、地域貢献活動の奨学生同士の情報交換という感じですか。"},{"i":89,"speaker":"まつざわ委員","text":"そうです。"},{"i":90,"speaker":"柏木子育て応援課長","text":"ですと、すみません、今はそういう場を設けるとかという考えはなかったものですから、いただいた意見を参考に、今後検討させていただきたいと思います。"},{"i":91,"speaker":"まつざわ委員","text":"あと１つ、連帯保証人なのですけれども、今回、連帯保証人は親がやりますよね。大学の承認をつけてやりますけれども、少し調べると、現在の奨学金は保証人不要型というのがあるのですか。例えばそういうのにすると、保証人不要型というのがある中で、区が連帯保証人という形を今回取ったわけですけれども、そうすると、連帯保証人をつけるという支援のハードルとか、そういった部分に対する妥当性といいますか、そういうのはどんな話合いがあったのかお聞かせください。"},{"i":92,"speaker":"柏木子育て応援課長","text":"連帯保証人の件でございますけれども、まず、この奨学金の給付につきましては、大学生本人に給付をするという形になりますので、もし万が一返還が必要となった場合は、その大学生に返還を求めなければいけないということになりますので、当然、学業ですとか、本人の経済状況等もございますので、その支払いを考えたときには、連帯保証人が必要だろうと判断し、今回、連帯保証人の設定をしてございます。また、高校生の奨学金事業も同じく、高校生ですので連帯保証人の設定をしてございます。\n連帯保証人は、特に誰という指定はないのですが、大体保護者等１名を想定してございます。"},{"i":93,"speaker":"つる委員長","text":"ほかにございますか。"},{"i":94,"speaker":"横山委員","text":"今、議論になったところなので、私も連帯保証人のところで気になっていた部分があるのですけれども、こちらなのですが、なかなか確保が難しいような、保護者の方がなかなか理解していただけないとか、何らかの理由があって、例えば本人のお気持ちとしたり、また、地域貢献活動をしたりとか、学業成績も優れていて、それ以外の部分は意欲もあってというところであっても、なかなかそこの部分だけのハードルを感じているような子がいた場合に、相談とか、問合せみたいなところを丁寧にお願いしていただきたいと思うのですけれども、必ずしも保護者がなる必要はないということですから、その辺りも寄り添った丁寧な問合せへの対応ですとか、お話を聞いていただきたいという思いが私としてはあるのですけれども、その辺りのところを教えてください。\nあと、（６）の予算規模の見込みのところなのですけれども、４年制大学であれば、令和７年から１０年度というところで、例えば今、６年制の医療系とか歯科・薬学というところもあると思いますので、令和１１年と１２年というのは今どのぐらいで、そもそも多分、もう見込みというのは立っているのではないかと思ったのですけれども、もしあれば教えてください。\nまた、学部についても、先ほどのご説明で理解したところではあるのですけれども、今後のお話でというところなのですが、例えば社会的養護の下で暮らしているようなお子さんの場合、芸術に秀でているお子さんというのも結構多いとは聞いているのですが、ただ、ここも高額になってしまいますので、なかなか進学というのが難しいという話も聞いたことがあります。\nそうした経済状況であったり家庭の環境であったりによらず、様々チャレンジができるというところを考えたときには、ＩＴとデザインみたいな形で、これから地域であったりとか、将来的に求められたりしてくるような部分もあるかと思いますので、その辺りも今後、検討の中に入れていただきたいと思いますので、それは一言だけいただければと思います。"},{"i":95,"speaker":"柏木子育て応援課長","text":"まず１つ目に、保証人等のお問合せの対応でございますけれども、保証人だけに限らず、お問合せいただいたときは、きちんと丁寧に対応しております。特に申請の際は、高校生ということもございますので、そこはきちんと対応していきたいと考えてございます。\n見込みの額でございますが、今回４年間出させていただきましたので、令和１１年度以降の見込みにつきましては、すみません、こちらについてはまだきちんとしたものができていない部分でございます。６年制の医学部等にどれぐらいいるのかによりまして変わりますので、そこの見込みはまだできてはございません。\n学部の拡大につきましては、今後、区民の方からいろいろなお声をいただくと思いますので、そういう声を聴きながら検討していきたいと考えてございます。"},{"i":96,"speaker":"横山委員","text":"初めてスタートしていくものですから、これから区民の方々ですとか、子どもたちご本人にもいろいろ意見を聴いていただいて、制度をよりすばらしいものにしていっていただきたいと思っておりますので、よろしくお願いいたします。"},{"i":97,"speaker":"つる委員長","text":"ほかにございますか。"},{"i":98,"speaker":"高橋（し）委員","text":"すみません、幾つかお尋ねします。\nまず１つ目は、学部の話が出ていたのですけれども、現在、情報学士というのがあって、情報学士は、いわゆる文系の学部でも、結局、事実上理系的な学習をしたりすることになり、それで事実上理系と言ってもいいようなものがあるのですけれども、それは選定委員会の中で、情報学は今非常に、先ほどもＩＴというお話が出ていましたけれども、希望する高校生が多いので、それも含めて、今年度対象にしていただきたいと思うのですが、その辺りは検討の余地があるのかどうかということです。文系の要素もありますけれども、経営工学とかの世界だと、それで情報学士とかになるので、そういったものも理系だと思うので、お願いします。そこを確認します。\n２つ目は、支給を停止するところに休学があったのですが、休学もいろいろ、ご病気での場合は駄目と書いてあるのですけれども、例えば留学をした場合に、最近大学では学年が留年しないように、いろいろ提携大学に行ったりして、単位が取れるようになっているのですけれども、幾つかの大学は２年から３年に上がれないなどというのがあるのですが、そういう場合は、支給についてどのような配慮がなされるのかというところ、多くの学生が留学することが多いので、そこが１つ。\nそれからもう１つは、第８条の５に不良の者とあったので、不良というのは、例えば留年したら駄目というのは書いてあるのですけれども、１つの科目でも不認定のものがあったらという意味なのか、結構曖昧に書いてあるので、その辺はどのように今お考えなのか、後で要綱で詰めていくというお話があったので、そこで出てくるのだとは思いますが。\nそれからもう１つは、先ほど申請者の名前は分からないようにするとあったのですけれども、区の関係者や、例えば議員の子弟からも、これは応募ができるのでしょうかというところの確認です。\nそれからもう１つは、ボランティアは本当に大事なので、ほかの委員の方がおっしゃったように、何とか柔軟性を持ちながらもしていただきたいのですが、ある大学では、奨学生たちがプロジェクトチームをつくって、いろいろなイベントで、その奨学生たちがごみの分別フェスティバルみたいなのをやったりしているので、先ほど検討していっていただくという話だったので、ぜひそういう奨学生によるプロジェクト、あるいはいろいろなものをやっていただきたいと思うのですが、そこの確認です。お願いします。"},{"i":99,"speaker":"柏木子育て応援課長","text":"初めに、情報学士が取れる文系のお話ですけれども、文部科学省の学校基本調査等の学部等も確認した上で、そこは今後詰めていきたいと思います。\n次に、休学でございますけれども、まず、第８条といたしましては、給付の決定の停止または取消しができる条件を書いてございますので、休学したからすぐ取消しになるのかという部分は、そういう考えではございません。休学した場合を例に取りますと、当然、病気ですとか、事故に遭ったとか、やむを得ない場合等もございます。また、先ほどありましたとおり、留学等で休学しているということも当然想定してございますので、その部分につきましては、本人の状況を確認した上で、運営委員会で審議して判断したいと考えてございます。\n次は、学業成績の不良でございますけれども、細かくこういう場合というのはまだ決めていない部分がございますが、少なくとも通常の修業期間で卒業ができないような場合が想定できると思います。なので、これでは４年間では全ての単位は取れませんとか、そういう部分があった場合については、取消しについて運営委員会で判断いただくという形になるかと。その詳細については今後詰めていく予定でございます。\n次は、区の職員ですとか、区議の子どもとかも申請できるのかと。特にそこは制限を設けてございませんので、申請は可能でございます。\nそれと、地域貢献のプロジェクトでございますが、今後検討していきたいと考えてございます。"},{"i":100,"speaker":"高橋（し）委員","text":"いろいろお尋ねしてお答えいただいたのですが、いろいろ本当に細かいところまで決めていかなければいけないので、大変だと思いますけれども、ぜひ多くの高校生が応募できて、それで奨学金を受けて、そういう大学に行って、それでその方々が区に貢献していけるようなというところまでお願いしたいと思います。\n最後に１点だけ、不良の話は、４年生まで奨学金をもらって勉強していたのだけれども、これで４年では卒業できないな、５年生になってねという話になったときには、５年生のときはもちろん奨学金は出ないですけれども、１年から４年までの全部を返してとなるのかどうかというところも、今後検討になるわけですか。"},{"i":101,"speaker":"柏木子育て応援課長","text":"返還の全部なのか一部なのかという部分につきましては、これまでのその子どもの活動等を踏まえた上で、運営委員会で審議をして決定するという運びになります。詳細は今後また詰めていきたいと考えてございます。"},{"i":102,"speaker":"高橋（し）委員","text":"現状の高校３年生、あるいはその後の２年生、１年生の保護者、本人も大変期待している仕組みですので、ぜひしっかりと進めていっていただきたいと思います。"},{"i":103,"speaker":"つる委員長","text":"ほかにございますか。"},{"i":104,"speaker":"若林委員","text":"第６条あたりに、奨学金の給付期間は、在学する大学の修業年限を満了するために必要な期間とすると。そうすると、第８条のいわゆる取消しとか返還、これの期限を定めてという返還についてはそういう表現ですが、これは要するに、返還の部分ですけれども、私たちがよく年度ごとに判断するという言い方と、ここでは修業年限全部を見て、この関係はどのようになるかなと。\n取り消しましょうと運営委員会で決定しましたと。その返還分は、もらった分を返還するわけですから、遡ってという見方です。私たちが普通に考えると、１年度ごとという感覚と、ここでは就学、１年生に入って、もらったときからというところ、この期限の定め方というのはどのような考え方なのかというのが１つ。\nそれから、いわゆる運営委員会の決定があって、一応、今のところ１００人ということで、当然、申請者数のほうが多いでしょうという見立ての中で、この決定に不服があったときの手続等の取決めが、この条例にはないのですが、なぜないのかというか、考え方というか、そこは手続がどうなるのかという、情報公開も含めて、情報公開しないと理由については明らかにできないのかというところを教えていただきたいなと。\nそれから、これは今年度、（５）のスケジュールには、一次・二次審査を経て３月に入学の確認と給付があるというスケジュールなのですが、来年度以降はなるべく早く申請を受け付けて、なるべく早く給付の決定をして、なるべく早く学生生活に資するように給付を始めていただきたい。ほかの奨学金制度もそのようになっていると思うのですけれども、来年度以降のスケジュールについて、どのような考え方かをお聞きしたいと思います。"},{"i":105,"speaker":"柏木子育て応援課長","text":"１つ目が返還に関わるお問合せでございますけれども、今やっています高校生の例を取りますと、通常の返還を求める場合は、その年度、最終年度といいますか、取消しになったときの年度ごとに返還を求めているということになっていますので、大学奨学金についても同様のとおりの取扱いになるかと思います。ただ、申請自体の不正があったとかという場合については、遡って最初の給付から返還いただくという形になるかと思います。\n次は、不服申立ての件でございますが、こちらは条例ではなくて、要綱等で決め、また、通知する際には、不服申立ての文面もきちんと入れた上で通知をしたいと考えてございます。\n来年度以降の給付のスケジュールですが、現状では今回と同様の考えでございますけれども、今、委員からいただいた意見も含めて、来年度のスケジュールについては改めて検討したいと考えてございます。"},{"i":106,"speaker":"若林委員","text":"来年度以降のスケジュールについては、４月に入学して３月に確認・給付というのは、現実的には、これを受けて大学に通う学生たちにとっては酷かなというところもありますので、ぜひ柔軟に、前向きに決めていただければと思います。"},{"i":107,"speaker":"つる委員長","text":"ほかにございますか。よろしいですか。"},{"i":108,"speaker":"筒井副委員長","text":"私からは、給付期間中、給付要件として、区内における地域貢献活動に定期的に参加できることというのがあるのですけれども、今回、目的として、将来、地域社会に貢献する人材を育成することを目的とするとありますが、今述べたように、給付期間中は区内において地域貢献活動をやることを要件に、やられると思うのですけれども、将来、地域社会に貢献する人材ということで、卒業した後、品川区内でいつまで働いていただけるのかとか、多分ずっと長い人生の中、縛ることはできないと思うのですけれども、ただ一方で、目的が、将来、地域社会に貢献する人材育成ということなので、その辺りの審査というか、縛りというか、そういうのはどの辺りまで考えられているのか、また、将来、地域社会に貢献する人材ということで、申請者の方が品川区内でぜひ働きたいですとか、そうしたことをアピールして、それを今回の運営委員会等々で審議して、この方が将来、地域社会に貢献する人材だということを判断するのか、その辺り、どのようにされていくのかお聞かせください。"},{"i":109,"speaker":"柏木子育て応援課長","text":"卒業後、区内の地域活動等に縛りとかというと、正直、今回の大学奨学金でそこまで言えるかというと、なかなか厳しいものがあるというのは感じてございますけれども、この大学奨学金で受けること、また、大学に在学中、地域に関わることで、品川区に愛着を持っていただいて、引き続き品川区に住んでいただいて、また地域貢献をしていただけるような方が出てきていただけるのが一番いいと考えてございますが、卒業後まで、繰り返しになりますが、縛りをつけられるかというと、そこは厳しい。ただ、この奨学金を通じて、改めて品川区に愛着を持っていただいて、住み続けていただきたいとは考えてございます。\nそれと、それに関わる審査でございますけれども、今、審査基準については、中で検討しているところでございますが、将来的なところも入れるのかどうかというのは、また検討の中で考えたいと思います。"},{"i":110,"speaker":"筒井副委員長","text":"当然、縛りというのは現実的に難しいと思うのですけれども、ただ、そういった現実的な状況がある中、申請者の方が申請段階で、すごく私は品川区のために、品川区に住んで、そして品川区の関連企業に入って、品川区に貢献したいという方がいらっしゃったら、それは結構ポイントが高いというか、優先順位が高くなると個人的に思うのですけれども、その辺り、今後の要綱等々で話していただけるとよいかと思いますので、これは要望であります。よろしくお願いします。"},{"i":111,"speaker":"つる委員長","text":"ほかにございますか。"},{"i":112,"speaker":"高橋（し）委員","text":"すみません、さっき聞き忘れてしまったのですけれども、日本学生支援機構の奨学金があると思うのですが、それを借りるときに、品川区からこの奨学金をもらっているとすると、それが借りられなくなってしまう可能性はあるのですか。それとも、それは大丈夫なのですか。そこだけ、私は詳しくないので、併用が可能だというのは今、お聞きしなくてはというのがあるのですけれども、認められない場合があるのかないのか、その点は申請する方にご説明する必要があると思いました。"},{"i":113,"speaker":"柏木子育て応援課長","text":"そちらの奨学金につきましては、品川区の奨学金と併用可能と確認してございます。"},{"i":114,"speaker":"高橋（し）委員","text":"そうすると、逆に日本学生支援機構の奨学金をもらっていても、品川区のほうは申請ができるということでよろしいですか。逆のこともオーケーだと。"},{"i":115,"speaker":"柏木子育て応援課長","text":"今、委員ご指摘のとおりでございます。"},{"i":116,"speaker":"つる委員長","text":"ほかにございますか。\nでは、１点だけ。これは周知というのは、どういうところ、範囲で今考えているのか、その辺を伺います。"},{"i":117,"speaker":"柏木子育て応援課長","text":"周知の方法でございますけれども、現時点の考えになりますが、まずは広報、あと、区のホームページ、区のＳＮＳです。それと、高等学校にチラシ、あと募集要項の配布を含めての周知も考えてございます。高等学校の範囲をどこまでにするのかというのは、今、検討しているところでございます。区内だけなのか、区周辺なのか、都全体なのかとか、その部分は今、検討しているところでございます。"},{"i":118,"speaker":"つる委員長","text":"対象が当然大学、ここにあるとおり、対象となっているところを目指している方が、申請者の部分を担うのだと思うのですけれども、もっと期間的にスパンを長期的に見ると、遡っていってみると、小学校受験があって、もっと言えば幼稚園受験もあるかもしれない。受験に限らずですけれども、その子が、また世帯が置かれている環境、そういう人たちがどういう将来の方向性を目指すか。それは品川区の奨学金の今回の設定の中にもある地域貢献ということも含めてですけれども、将来を見越して見立てて、その方向性をやっていくと思うのです。そこが経済的な事由、理由を持って、その方向性を断念してしまうというのが、どの段階でもあるとは思うのです。\nそうすると、幅広の政策的な日本の中では、高等教育、大学も含めたものを無償化というか、学問にお金がかからずにという大きな流れはあるのだと思うのですけれども、それはまだ過渡的な現状で、品川区もこうした形で今、応援していただくという条例が今回上がっているわけですが、もう少し早い段階で、これは大学だけではなくて、既存の高校もそうなのですが、行政間で、例えば広域の東京都も含めて、いろいろな支援策が経済的な部分にもあると思うのです。\nそうしたものを早い段階で、それこそ小学校だ、中学校だというところでも、情報提供という意味では、先ほどあった広報とかホームページというところで、それぞれをそれぞれの方が見ていただくとなるのだと思うのですが、いろいろな段階で、こういう経済的な部分においても支援があるというのは、ある程度パッケージで提示したほうが分かりやすいのではないか。将来こういう支援があるのだったら、この小学校を目指していこう、中学校を目指していこう、高校を目指していこうというような考え方もあるだろうなと。\n当然、今、高橋しんじ委員からあった、いろいろな奨学金をやっている、学校でもやっていたりするのがあると思うのです。区としては、こういった形の情報提供というのは、今、高校という話がありましたけれども、もう少し早い段階でも、こういったこともあるよという参考程度にやることも、非常に効果的ではないかと思うのですが、その辺の考え方を最後に教えてください。"},{"i":119,"speaker":"柏木子育て応援課長","text":"早い段階への周知という部分でございますけれども、すみません、持ち帰って検討させていただきたいと思います。"},{"i":120,"speaker":"つる委員長","text":"よろしくお願いします。\nほかにございますか。よろしいでしょうか。\nほかにご発言がないようですので、これで質疑を終了いたします。\n採決に入ります前に、まず、第７６号議案、品川区給付型大学奨学金条例につきまして、各会派の態度を確認いたします。\nそれでは、品川区議会自民党・無所属の会からお願いいたします。"},{"i":121,"speaker":"まつざわ委員","text":"賛成です。"},{"i":122,"speaker":"筒井副委員長","text":"賛成です。"},{"i":123,"speaker":"若林委員","text":"賛成です。"},{"i":124,"speaker":"のだて委員","text":"賛成です。"},{"i":125,"speaker":"高橋（し）委員","text":"賛成です。"},{"i":126,"speaker":"横山委員","text":"賛成です。"},{"i":127,"speaker":"つる委員長","text":"それではこれより、第７６号議案、品川区給付型大学奨学金条例について、採決いたします。\nお諮りいたします。\n本案は、原案のとおり決定することにご異議ありませんか。\n〔「異議なし」と呼ぶ者あり〕"},{"i":128,"speaker":"つる委員長","text":"ご異議なしと認めます。よって、本案は全会一致で原案のとおり可決決定いたしました。\n次に、第７７号議案、品川区給付型大学奨学金運営委員会条例につきまして、各会派の態度を確認いたします。\nそれでは、品川区議会自民党・無所属の会からお願いいたします。"},{"i":129,"speaker":"まつざわ委員","text":"賛成です。"},{"i":130,"speaker":"筒井副委員長","text":"賛成です。"},{"i":131,"speaker":"若林委員","text":"賛成です。"},{"i":132,"speaker":"のだて委員","text":"賛成です。"},{"i":133,"speaker":"高橋（し）委員","text":"賛成です。"},{"i":134,"speaker":"横山委員","text":"賛成です。"},{"i":135,"speaker":"つる委員長","text":"それではこれより、第７７号議案、品川区給付型大学奨学金運営委員会条例について、採決いたします。\nお諮りいたします。\n本案は、原案のとおり決定することにご異議ありませんか。\n〔「異議なし」と呼ぶ者あり〕"},{"i":136,"speaker":"つる委員長","text":"ご異議なしと認めます。よって、本案は全会一致で原案のとおり可決決定いたしました。\n以上で本件を終了いたします。\n子育て応援課長は、ここでご退席いただいて結構でございます。ありがとうございました。\n────────────────────────────────────────────\n(5) 第８０号議案 品川区家庭的保育事業等の設備および運営の基準に関する条例の一部を改正する条例"},{"i":137,"speaker":"つる委員長","text":"次に、(5)第８０号議案、品川区家庭的保育事業等の設備および運営の基準に関する条例の一部を改正する条例を議題に供します。\nそれでは、本件につきまして、理事者よりご説明願います。"},{"i":138,"speaker":"佐藤保育事業担当課長","text":"それでは私より、第８０号議案、品川区家庭的保育事業等の設備および運営の基準に関する条例の一部を改正する条例についてご説明申し上げます。資料をご覧ください。\n初めに、１番、改正理由でございます。\n地域の自主性及び自立性を高めるための改革の推進を図るための関係法律の整備に関する法律（地方分権一括法）により、栄養士法が改正されました。それを受けまして、従前、管理栄養士国家試験は、栄養士の免許を受けた者でなければ受けることができませんでした。しかし、改正後において、管理栄養士養成施設の卒業者については、栄養士の免許の取得が不要となりました。\nこの栄養士法の改正を踏まえまして、栄養士の配置などを求めている国の家庭的保育事業等の設備及び運営に関する基準が、栄養士免許を有さない管理栄養士を配置した場合についても要件を満たすように改正されました。国の基準改正に伴いまして、区の基準について改正を行うものでございます。\n続きまして、２番、改正内容でございます。栄養士の配置を求めている規定において、管理栄養士を追加するものでございます。\n３番、改正案、別紙「新旧対照表」をご覧ください。\n品川区家庭的保育事業等の設備および運営の基準に関する条例ですが、第１７条に、利用乳幼児に対する食事の提供に関する特例が規定してございます。条例で配置を求めている栄養士による献立指導等につきまして、改正により、栄養士免許を有さない管理栄養士であっても基準を満たすことができることとするものでございます。\nなお、本改正は、国の基準に従うべき事項とされているものでございます。\n４番、施行日でございますが、公布の日となっております。"},{"i":139,"speaker":"つる委員長","text":"説明が終わりました。ご質疑等がございましたら、ご発言願います。"},{"i":140,"speaker":"のだて委員","text":"今回、管理栄養士養成施設卒業者が、栄養士の免許を取得していなくて管理栄養士になれるということで、この卒業者というのは、栄養士と同等の知識などを持っているのかどうかというところを伺いたいと思います。つまり、安全性が変わらないのかどうかというところを伺いたいのと、あと、区内ではこの対象になるところがあるのかどうか伺います。"},{"i":141,"speaker":"佐藤保育事業担当課長","text":"まず、管理栄養士養成施設卒業者について、栄養士と同等の知識があるのかということでございますけれども、こちらは知識がある者であると認められております。\nまた、対象施設についてでございますが、今回の対象の特例の適用を受ける施設ということでございますが、区内にあります家庭的保育事業所等の中で、自園調理を行っていない施設というのはほぼ、ありませんので、本改正に与える影響というのはほとんどないと考えております。"},{"i":142,"speaker":"のだて委員","text":"管理栄養士養成施設卒業者は同等の知識を持っているということなので、安全性は変わらないということでよろしいですか。"},{"i":143,"speaker":"佐藤保育事業担当課長","text":"おっしゃるとおりでございます。"},{"i":144,"speaker":"つる委員長","text":"ほかにございますか。よろしいでしょうか。\nほかにご発言がないようですので、これで質疑を終了いたします。\n採決に入ります前に、第８０号議案、品川区家庭的保育事業等の設備および運営の基準に関する条例の一部を改正する条例につきまして、各会派の態度を確認いたします。\nそれでは、品川区議会自民党・無所属の会からお願いいたします。"},{"i":145,"speaker":"まつざわ委員","text":"賛成です。"},{"i":146,"speaker":"筒井副委員長","text":"賛成です。"},{"i":147,"speaker":"若林委員","text":"賛成です。"},{"i":148,"speaker":"のだて委員","text":"賛成です。"},{"i":149,"speaker":"高橋（し）委員","text":"賛成です。"},{"i":150,"speaker":"横山委員","text":"賛成です。"},{"i":151,"speaker":"つる委員長","text":"それではこれより、第８０号議案、品川区家庭的保育事業等の設備および運営の基準に関する条例の一部を改正する条例について、採決いたします。\nお諮りいたします。\n本案は、原案のとおり決定することにご異議ありませんか。\n〔「異議なし」と呼ぶ者あり〕"},{"i":152,"speaker":"つる委員長","text":"ご異議なしと認めます。よって、本案は全会一致で原案のとおり可決決定いたしました。\n────────────────────────────────────────────\n(6) 第８１号議案 品川区児童福祉施設の設備および運営の基準に関する条例の一部を改正する条例"},{"i":153,"speaker":"つる委員長","text":"次に、(6)第８１号議案、品川区児童福祉施設の設備および運営の基準に関する条例の一部を改正する条例を議題に供します。\nそれでは、本件につきまして、理事者よりご説明願います。"},{"i":154,"speaker":"佐藤保育事業担当課長","text":"それでは私より、第８１号議案、品川区児童福祉施設の設備および運営の基準に関する条例の一部を改正する条例についてご説明申し上げます。資料をご覧ください。\n初めに、１番、改正理由でございます。\n東京都において、東京都認証保育所におけるインクルーシブ保育を推進するため、令和７年４月１日付で東京都児童福祉施設の設備及び運営の基準に関する条例と、同条例施行規則が改正されました。これに伴い、都基準条例および同条例施行規則を参酌して定めている品川区児童福祉施設の設備および運営の基準に関する条例を改正する必要があるためでございます。\n続きまして、２番、改正内容でございます。\n従来、東京都認証保育所と児童発達支援センターの専従の人員の兼務というのは不可でして、それぞれに保育・療育を行ってございました。先般、都基準条例および同条例施行規則が改正され、保育所、児童発達支援センターの基準を満たした上で、利用児童の保育および障害児の支援に支障が生じない場合に限り、それぞれの施設が交流を行う場合に、専従の人員を兼務して一体的な支援を行うことを可能とするものでございます。\n３番、改正案、別紙「新旧対照表」をご覧ください。\n第９条に新たに「児童発達支援センターの職員」という項目を設けて、児童発達支援センターの職員が保育に従事できる場合を規定し、そのほか、表記を修正したものでございます。\nなお、厚生委員会におきまして同様に、品川区指定障害児通所支援の事業等の人員、設備および運営の基準等に関する条例改正が提出されております。\n４番、施行日でございますが、公布の日となっております。"},{"i":155,"speaker":"つる委員長","text":"説明が終わりました。ご質疑等がございましたら、ご発言願います。"},{"i":156,"speaker":"のだて委員","text":"今回、この条例改正をしないと、認証保育所と児童発達支援センターの子どもたちが交流することというのはできないのかどうか伺います。"},{"i":157,"speaker":"佐藤保育事業担当課長","text":"改正を行えない場合は、保育所の施設と児童発達支援センターに通われている児童が交流したりするということが、今の段階ではできないというものでございます。"},{"i":158,"speaker":"のだて委員","text":"できないということで、やるにはこの改正が必要だということですね。今の話だと、交流できない。\n〔「先生の兼務だから」と呼ぶ者あり〕"},{"i":159,"speaker":"のだて委員","text":"具体的にできないというところがあれば伺いたいと思います。まずそれを伺います。"},{"i":160,"speaker":"佐藤保育事業担当課長","text":"説明が分かりづらくて大変申し訳ございませんでした。一般的な公園とかで交流するということは可能なのですけれども、保育所において、保育所の施設内で一緒に保育を行うということはできないというものでございます。"},{"i":161,"speaker":"のだて委員","text":"なるほど。公園ではできるけれども、保育園内ではできないということになるということですね。\n今回それができるようになるということで、１つ危惧をしているのは、兼務することで、人員配置が緩和されてしまうということにならないのかと思っているのですが、そこを伺いたいのと、あと、区内にはこういった施設はあるのかどうかと、今後何かできる予定、見込みみたいなのはあるのでしょうか。"},{"i":162,"speaker":"佐藤保育事業担当課長","text":"本改正によって人員配置等が緩和されるのではないかというご質問でございますけれども、これは利用児童の保育および障害児の支援に支障が生じない場合に限り、保育等ができることになってございます。ですので、それぞれの基準というのを満たした上でないと保育等はできませんので、安全基準に関しては、従来と変わらないものであると考えてございます。\nまた、こういった施設があるのかというご質問でございますけれども、区内に認証保育所と児童発達支援センターが併設しているような施設というのは、現在はございません。が、認可保育所においては１施設、私立において保育所と児童発達支援センターが併設されている施設はございます。"},{"i":163,"speaker":"のだて委員","text":"今後の見込みですが。"},{"i":164,"speaker":"佐藤保育事業担当課長","text":"今後の見込みでございますが、今、認証保育所等におきまして、こうした併設を計画されているといったお声というのは聞いておりません。"},{"i":165,"speaker":"つる委員長","text":"ほかにございますか。よろしいですか。\nほかにご発言がないようですので、これで質疑を終了いたします。\n採決に入ります前に、第８１号議案、品川区児童福祉施設の設備および運営の基準に関する条例の一部を改正する条例につきまして、各会派の態度を確認いたします。\nそれでは、品川区議会自民党・無所属の会からお願いいたします。"},{"i":166,"speaker":"まつざわ委員","text":"賛成です。"},{"i":167,"speaker":"筒井副委員長","text":"賛成です。"},{"i":168,"speaker":"若林委員","text":"賛成です。"},{"i":169,"speaker":"のだて委員","text":"インクルーシブ保育を進めていくためのものですので、賛成です。"},{"i":170,"speaker":"高橋（し）委員","text":"賛成です。"},{"i":171,"speaker":"横山委員","text":"賛成します。"},{"i":172,"speaker":"つる委員長","text":"それではこれより、第８１号議案、品川区児童福祉施設の設備および運営の基準に関する条例の一部を改正する条例について、採決いたします。\nお諮りいたします。\n本案は、原案のとおり決定することにご異議ありませんか。\n〔「異議なし」と呼ぶ者あり〕"},{"i":173,"speaker":"つる委員長","text":"ご異議なしと認めます。よって、本案は全会一致で原案のとおり可決決定いたしました。\n────────────────────────────────────────────\n(7) 第８２号議案 品川区乳児等通園支援事業の設備および運営の基準に関する条例"},{"i":174,"speaker":"つる委員長","text":"次に、(7)第８２号議案、品川区乳児等通園支援事業の設備および運営の基準に関する条例を議題に供します。\nそれでは、本件につきまして、理事者よりご説明願います。"},{"i":175,"speaker":"佐藤保育事業担当課長","text":"それでは私より、第８２号議案、品川区乳児等通園支援事業の設備および運営の基準に関する条例についてご説明申し上げます。資料をご覧ください。\n１番、制定理由でございます。\n子ども・子育て支援法等の一部を改正する法律の公布により、保育施設等に在園していない満３歳未満の乳幼児を対象に、保護者の就労要件等を問わず柔軟な保育施設等の利用を可能とする「こども誰でも通園制度」が創設されました。また、上記法によりまして、児童福祉法が改正され、乳児等通園支援事業の設備及び運営に関する基準について、必要な基準を条例で定めなければならないとされたためでございます。\n続きまして、２番、制定内容（概要）でございます。別紙１の条例案をご覧ください。\n１番、趣旨につきまして、第１条で規定してございます。本条例につきましては、乳児等通園支援事業の設備および運営に関する基準（最低基準）を定めるものでございます。\n２番、乳児等通園支援事業者の一般原則について、第６条で規定してございます。\n３番、設備の基準、４番、職員の基準を、第２２条、第２３条、第２６条で規定してございます。また、適用する基準につきましては、現在運営されている認可保育所等の基準と同水準の基準としてございます。\n４番、施行日でございますが、公布の日となっております。"},{"i":176,"speaker":"つる委員長","text":"説明が終わりました。ご質疑等がございましたら、ご発言願います。"},{"i":177,"speaker":"のだて委員","text":"まず、区の今まで実施してきたトキドキ保育との関係性というのはどうなるのかというのと、これは国が法改正して、こども誰でも通園制度ができたということで、これを区でもできるようにするのだと思うのですけれども、区としてはこれを実施していくつもりなのか伺います。"},{"i":178,"speaker":"佐藤保育事業担当課長","text":"今現在、区で実施しておりますトキドキ保育との関係性についてのご質問でございますが、現在実施している事業は、東京都の補助事業というのを活用した事業でございます。令和８年度から実施されます国の制度との違いでございますけれども、大きな目的としては、未就学児に対する成長環境というのを提供するということで、目的は同じなのですけれども、違いといたしましては、対象児童の年齢や利用時間というものの違いがございます。\n続きまして、区としてこれを実施していくのかということでございますが、誰でも通園制度は、令和８年度になりますと給付事業となりまして、全国の自治体が実施しなければならないものであると定められてございますので、実施をしていくものでございます。"},{"i":179,"speaker":"のだて委員","text":"実施しなければならないというところで、そうすると、区立の保育園でも実施していくという考えなのか伺いたいと思います。"},{"i":180,"speaker":"佐藤保育事業担当課長","text":"実施施設についてでございますけれども、現在検討中でございまして、ニーズですとか、あとは本事業を実施していただく施設といったものを勘案しながら、区立での実施についても検討していきたいと考えております。"},{"i":181,"speaker":"のだて委員","text":"これを実施していくに当たっては、いろいろ慎重にやっていかなければいけないと思うのです。誰でも通園制度なので、子育てで孤立する方が出ないように、一回休憩するというか、一休みするという意味でも、これは重要だとは思うのですけれども、通常通っている子どもたちとは違って、子どもたちは基本的に１年は通うわけですけれども、誰でも通園制度だと週一、二回になるという感じだと思うのですが、そうすると、慣れるまでに時間がかかるとかすると、この子が泣いてしまうとほかの子どもたちも一緒に泣いてしまうということとかで、いろいろ保育士にも負担がかかるし、泣く状況になってしまうので、その子にも負担がかかるということになってしまうと思うのです。\nなので、保育士の配置をきちんとしていかないと、これは子どもにとっても保育士にとっても負担が大きくなるということになってしまうと思うのですけれども、保育士の配置基準を伺いたいのと、保育士の方からお話を伺うと、常に来る子ではない子が入ってくるとなると、そういう落ち着かない部分が多くなってくるので、１人に対して１人の保育士で見られるようにしてほしいと要望があったので、実施していただきたいと思うのですが、いかがでしょうか。\nそれと、そのように泣いてしまうということがあるので、同じ場所で保育していると、ほかの子どもたちにも影響が出てしまうということになるので、別室で落ち着かせるようなスペースがないといけないということもお聞きしまして、そうした施設的な整備もやっていくことが必要だと思うのですけれども、いかがでしょうか。"},{"i":182,"speaker":"佐藤保育事業担当課長","text":"まず、保育士の配置基準に関するお尋ねについてご回答させていただきます。本条例で制定しておりますように、今現在、区で適用されている保育所等の配置基準と同等の配置基準というのを、誰でも通園においても求めていくものでございます。お話がございましたように、現場の保育士の負担というのは我々としても把握してございまして、非常に大切なテーマであると考えているところでございます。\n令和６年度、都の事業を活用して事業実施しているのですけれども、そのときに、補助の対象経費だったり、補助額というのを拡大したりして実施してございます。その実施を用いまして、事業者の方たちは流動的に人材を確保したり、またはＩＣＴ機器を導入することによって保育士の負担を軽減したり、安全対策を実施したりしていただけるような取組というのを実施しているところでございます。\nもう１つ、別室で落ち着かせるスペースが欲しいということに対してでございますけれども、本事業は２つの形式で事業実施ができまして、１つは一般型と言われるもので、今お話をされたような別室を施設で用意して実施する事業でございます。もう１つが余裕活用型という事業でございまして、今現在、各保育所に定められている定員の空き分を使った事業ということでございます。\nこのスペースについては、なかなか事業所で確保することが難しいというところではございますけれども、今年度では１０程度の事業所において、一般型のスペースを活用した事業実施をしているというところでございますので、区としてもそうした事業者のお話を聞きながら、支援策などについては検討していきたいと考えてございます。"},{"i":183,"speaker":"のだて委員","text":"一応、支援策を考えていきたいということでした。そのためには、やはり保育士の配置をしっかりやっていくということで、配置基準は保育園と同じだということなのですけれども、保育園の基準というのは、常に子どもたちが来る子どもたちとして、だんだん慣れていきますし、その子の性格というか、対応も分かってくるということになりますけれども、誰でも通園制度だと、その子の好みも分からないですし、なかなかお昼寝もできない子もいるというお話も聞きました。\nそのように、いろいろ慣れるまでに時間がかかってしまうというところで、ほかの子どもたちにも影響が出てしまうということになりますので、ぜひ保育士を１人につき１人配置するという形でやっていくということが、本当に安全にもなりますし、保育士への負担も減る、子どもたちへの負担も減るということになると思いますので、それを改めて求めたいと思います。いかがでしょうか。\n安全面という面でも、保育の死亡事故も、預けたとき、最初のときに一番危険があるということですので、誰でも通園制度だと、いろいろな子どもたちが代わりばんこに来ることになりますので、そうすると、初めてというのが非常に多くなるということになると思いますので、安全面を見ても、１人に対して１人いるということが重要ではないかと思うのですけれども、その点も伺いたいと思います。\n実際の保育の現場の意見をしっかりと聞いていただきたいと。先ほどもいろいろ聞いているというお話でしたけれども、そこの意見を聞き取って、しっかり子どもたちにとっても、そして保育現場にも負担がかからないようにしていっていただきたいと思いますけれども、いかがでしょうか。"},{"i":184,"speaker":"佐藤保育事業担当課長","text":"保育所の配置基準、１対１での配置基準についてでございますけれども、当然、保育士の方がしっかりと配置されていることというのが、お子様にとって大切なことであると考えてございますので、先ほどお伝えしたような補助制度の対象経費の拡大や、補助額の拡大という取組を通じて、事業者の方に保育士を配置いただけるような、雇用をしていただけるような環境支援というのをしていきたいと考えております。"},{"i":185,"speaker":"のだて委員","text":"支援をしていくということで、ぜひ人員配置、そして別室を用意できるといった支援をしていっていただきたいと思います。そうしないと、事故の危険もありますし、子どもたちや保育職員の負担にもなってきますので、そうしたことが必要だと。それがなければ、実施していくということは慎重になるべきだと思います。\n配置も含めて、実際これが子どもたちにとっていいことなのかということだと思うのです。そこのところを区としてもどのように考えているのかというところを伺いたいと思います。今、いろいろな課題が出ている中で、子どもたちにも負担がかかっていると思うのですけれども、いかがでしょうか。"},{"i":186,"speaker":"佐藤保育事業担当課長","text":"まず別室の整備と人員配置につきましては、区としてどういったことができるのかにつきまして、様々継続して議論をしていきたいと考えてございます。\nまた、誰でも通園制度が子どもにとってどういった制度なのかということについてでございますけれども、まず、未就学児の方が家族以外の方と関わる経験をするということで、全ての子どもの育ちを応援していける環境整備というのが大切ではないかと思っております。"},{"i":187,"speaker":"のだて委員","text":"子どもたちが集団で遊んだりすることを経験したりするということは、子どもたちの成長にもつながるので、そうした機会があるということは必要だと思いますけれども、今のまま進めると、負担が大きく子どもにも職場にもかかってしまうと思います。\n今回の国の制度ですと、事業者で参入できるのが株式会社を含め、営利企業も参入可能だと思うのですが、そこのところを伺いたいのと、そうした企業が入ってくると、保育の施設ですとか、経験豊富な保育士をきちんと確保できるのかという問題があると思うのですけれども、いかがでしょうか。"},{"i":188,"speaker":"佐藤保育事業担当課長","text":"本事業の参加できる企業についてでございますけれども、まず、本事業は区として認可をした事業所に実施していただくということになりますので、しっかりと人員配置でありましたり、実施する施設の基準であったりというのは把握した上で認可をしていきますので、安全面にとっても十分に対応できるような事業者に実施をしていただくように考えております。"},{"i":189,"speaker":"のだて委員","text":"十分な配慮をする、認可できちんと確認していくということですけれども、様々な子どもたちが代わりばんこに来るわけなので、経験豊かな保育士が必要になってきますので、なかなか確保していくというのは難しいと思いますし、営利企業の参入というのは、そういう面でもやめるべきだと求めておきたいと思います。"},{"i":190,"speaker":"つる委員長","text":"ほかにございますか。よろしいでしょうか。\nほかにご発言がないようですので、これで質疑を終了いたします。\n採決に入ります前に、第８２号議案、品川区乳児等通園支援事業の設備および運営の基準に関する条例につきまして、各会派の態度を確認いたします。\nそれでは、品川区議会自民党・無所属の会からお願いいたします。"},{"i":191,"speaker":"まつざわ委員","text":"賛成です。"},{"i":192,"speaker":"筒井副委員長","text":"賛成です。"},{"i":193,"speaker":"若林委員","text":"賛成です。"},{"i":194,"speaker":"のだて委員","text":"今のままでは、子どもにも職員にも負担がかかると思いますので、これは反対いたします。"},{"i":195,"speaker":"高橋（し）委員","text":"賛成です。"},{"i":196,"speaker":"横山委員","text":"賛成します。"},{"i":197,"speaker":"つる委員長","text":"それではこれより、第８２号議案、品川区乳児等通園支援事業の設備および運営の基準に関する条例について、採決いたします。\n本案は、挙手により採決いたします。\n本案は、原案のとおり決定することに賛成の方は、挙手願います。\n〔賛成者挙手〕"},{"i":198,"speaker":"つる委員長","text":"賛成多数でございます。よって、本案は原案のとおり可決決定いたしました。\n────────────────────────────────────────────\n(3) 第７８号議案 品川区保育の実施等に関する条例の一部を改正する条例\n(4) 第７９号議案 品川区私立認定こども園、私立幼稚園および特定地域型保育事業の利用者負担額に関する条例の一部を改正する条例"},{"i":199,"speaker":"つる委員長","text":"次に、(3)第７８号議案、品川区保育の実施等に関する条例の一部を改正する条例、(4)第７９号議案、品川区私立認定こども園、私立幼稚園および特定地域型保育事業の利用者負担額に関する条例の一部を改正する条例の２議案を議題に供します。\nこれらの議案につきましては、関連する内容のため、一括して説明、質疑を行い、その後、議案ごとに採決を行いたいと思いますので、よろしくお願いいたします。\n本件につきまして、理事者よりご説明願います。"},{"i":200,"speaker":"芝野保育入園調整課長","text":"それでは私から、第７８号議案、品川区保育の実施等に関する条例の一部を改正する条例および第７９号議案、品川区私立認定こども園、私立幼稚園および特定地域型保育事業の利用者負担額に関する条例の一部を改正する条例について、一括してご説明させていただきます。資料をご覧ください。\n初めに項番１、改正理由でございます。子育て世帯が認可保育施設を利用した際に負担する保育料を軽減することにより、区民が安心して子どもを産み育てることができる環境づくりを推進するため、東京都が実施する保育所等利用世帯負担軽減事業を活用し、第１子の保育料を無償とするための規定整備を行うものであります。\n次に、項番２、改正内容でございます。認可保育園、認定こども園、地域型保育事業に在籍しているゼロから２歳の児童における第１子の月額保育料を無償とするもので、（１）のとおり、令和７年９月分保育料より適用となります。\n（２）の延べ対象者ですが、１万６,７８６人を見込んでおります。\n（３）の影響額といたしましては、約７億円、利用者の経済的負担を軽減するものとなっております。\n次に、項番３、対象施設につきましては、記載のとおりでございます。\n項番４、補助率でございますが、区立園は２分の１、私立園は１０分の１０となっております。\n項番５、新旧対照表につきましては、別紙としておつけさせていただいております。\n項番６、施行期日は、令和７年９月１日でございます。"},{"i":201,"speaker":"つる委員長","text":"説明が終わりました。\n本件に関しまして、ご質疑等がございましたらご発言願います。"},{"i":202,"speaker":"のだて委員","text":"今回、第１子の無償化ということで、子育ての負担を軽減することはいいことだと思います。\n確認なのですけれども、資料の中で新旧対照表のところで、最後のほうに延長保育料のところが出てくるのですが、赤い字になっていると思うのですけれども、ここについては変更があるのかどうか伺いたいと思います。\nそれと、認証保育園がどうなっているのかも含めて、認証保育園は対象施設の中には入っていないのですが、現状を伺いたいと思います。"},{"i":203,"speaker":"芝野保育入園調整課長","text":"２つのご質問をいただきました。\nまず、延長保育料の変更でございますが、今回の条例の改正附則で改正させていただく形になっております。従来の延長保育料の規定と特に大きな変更はございませんが、今回この条例から、所得別の別表が削除されてしまいますので、それを引用していた延長保育料の条例が、逆にこれを入れないとお金が取れなくなってしまいますので、こちらで入れさせていただいているところでございます。少しややこしいのですが、そういう形になっております。\nあと、認証保育所のほうはどうなっているかというご質問でございますが、認証保育所は認可外保育施設に当たりますので、この後、補正のお願いをさせていただいております認可外保育施設の保育料助成金の拡充のほうで担保していくという形になってございます。"},{"i":204,"speaker":"つる委員長","text":"ほかにございますか。\n〔「なし」と呼ぶ者あり〕"},{"i":205,"speaker":"つる委員長","text":"ほかにご発言がないようですので、これで質疑を終了いたします。\n採決に入ります前に、まず、第７８号議案、品川区保育の実施等に関する条例の一部を改正する条例につきまして、各会派の態度を確認いたします。\nそれでは、品川区議会自民党・無所属の会からお願いいたします。"},{"i":206,"speaker":"まつざわ委員","text":"賛成です。"},{"i":207,"speaker":"筒井副委員長","text":"賛成です。"},{"i":208,"speaker":"若林委員","text":"賛成です。"},{"i":209,"speaker":"のだて委員","text":"賛成です。"},{"i":210,"speaker":"高橋（し）委員","text":"賛成です。"},{"i":211,"speaker":"横山委員","text":"賛成です。"},{"i":212,"speaker":"つる委員長","text":"それではこれより、第７８号議案、品川区保育の実施等に関する条例の一部を改正する条例について、採決いたします。\nお諮りいたします。\n本案は、原案のとおり決定することにご異議ありませんか。\n〔「異議なし」と呼ぶ者あり〕"},{"i":213,"speaker":"つる委員長","text":"ご異議なしと認めます。よって、本案は全会一致で原案のとおり可決決定いたしました。\n次に、第７９号議案、品川区私立認定こども園、私立幼稚園および特定地域型保育事業の利用者負担額に関する条例の一部を改正する条例につきまして、各会派の態度を確認いたします。\nそれでは、品川区議会自民党・無所属の会からお願いいたします。"},{"i":214,"speaker":"まつざわ委員","text":"賛成です。"},{"i":215,"speaker":"筒井副委員長","text":"賛成です。"},{"i":216,"speaker":"若林委員","text":"賛成です。"},{"i":217,"speaker":"のだて委員","text":"賛成です。"},{"i":218,"speaker":"高橋（し）委員","text":"賛成です。"},{"i":219,"speaker":"横山委員","text":"賛成です。"},{"i":220,"speaker":"つる委員長","text":"それではこれより、第７９号議案、品川区私立認定こども園、私立幼稚園および特定地域型保育事業の利用者負担額に関する条例の一部を改正する条例について、採決いたします。\nお諮りいたします。\n本案は、原案のとおり決定することにご異議ありませんか。\n〔「異議なし」と呼ぶ者あり〕"},{"i":221,"speaker":"つる委員長","text":"ご異議なしと認めます。よって、本案は全会一致で原案のとおり可決決定いたしました。\n────────────────────────────────────────────\n(11) 第７１号議案 令和７年度品川区一般会計補正予算（歳出 文教委員会所管分）"},{"i":222,"speaker":"つる委員長","text":"次に、(11)第７１号議案、令和７年度品川区一般会計補正予算（歳出 文教委員会所管分）を議題に供します。\nそれでは、本件につきまして、理事者よりご説明願います。"},{"i":223,"speaker":"佐藤子ども未来部長","text":"私からは、第７１号議案、令和７年度品川区一般会計補正予算についてご説明を申し上げます。恐れ入りますが、ＳｉｄｅＢｏｏｋｓの資料、参考、令和７年度品川区一般会計補正予算の１６ページをご覧ください。\n今回の補正予算は、主に都の補助金を活用し、各種事業の充実を図るものであります。\nまず、３款民生費、２項児童福祉費、４目保育入園調整費に２億６７７万８,０００円を追加し、４８億６,０２１万円とするものです。これは、認可外保育施設等保育料助成およびベビーシッター利用支援事業費の増額分となります。\n次に、５目保育施設運営費です。８,７５９万５,０００円を追加し、３８７億３,９１５万２,０００円とするものです。これは、病児保育新規開設補助経費等の増額、病児保育予約システム運用経費として、認可外保育施設等におけるとうきょうすくわくプログラム推進経費の計上によるものでございます。\n詳細につきましては、担当の課長よりご説明いたします。"},{"i":224,"speaker":"芝野保育入園調整課長","text":"それでは私から、第７１号議案、令和７年度品川区一般会計補正予算、認可外保育施設等保育料助成金の拡充およびベビーシッター利用支援事業の助成内容の拡充について、一括してご説明させていただきます。資料をご覧ください。\n初めに、認可外保育施設等保育料助成金の拡充についてでございます。\n項番１、事業概要でございます。東京都の認可外保育施設利用支援事業補助金について、令和７年９月より補助上限額が従前より引き上げられることに伴い、区の助成金においても同水準まで補助上限を引き上げることで、認可外保育施設を利用する児童の保護者に対する経済的負担の一層の軽減を図るものでございます。\n次に、項番２、拡充内容でございます。表の下段、拡充後をご覧ください。拡充後は、所得に関わらず、ゼロから２歳児は月額８万円、３から５歳児は月額７万７,０００円まで補助上限を引き上げるものとなっております。\n次に、項番３、補正予算額でございますが、歳出補正額として１億６,３０４万４,０００円、歳入補正額として、東京都の認可外保育施設利用支援事業補助金を活用し、１億４,２６５万６,０００円でございます。\n最後に、項番４、スケジュールでございますが、本件議決後、速やかに保護者および事業者に対して拡充内容の周知を図り、９月より補助上限額の引上げを予定しております。\n続きまして、ベビーシッター利用支援事業の助成内容拡充についてでございます。資料をご覧ください。\n初めに、項番１、事業概要でございます。東京都のベビーシッター利用支援事業補助金について、令和７年度より対象年齢および利用上限時間の拡充が行われることに伴い、区の助成事業においても同様の拡充を実施することで、子育て世帯に対する経済的負担の一層の軽減を図るものでございます。\n次に、項番２、拡充内容でございます。\n（１）の障害児につきましては、対象年齢を小学６年生まで、利用上限時間を年間２８８時間まで拡充いたします。\n（２）のひとり親家庭の児童につきましては、利用上限時間を年間２８８時間まで拡充いたします。\n次に、項番３、補正予算額でございますが、歳出補正額として４,３７３万４,０００円、歳入補正額として、東京都のベビーシッター利用支援事業補助金を活用し、４,３２５万円でございます。\n最後に、項番４、スケジュールでございますが、本件議決後、速やかに利用者に対し、ご案内および申請受付を開始いたします。なお、利用につきましては、令和７年４月分より適用するものといたします。"},{"i":225,"speaker":"染谷保育施設運営課長","text":"私からは、ＳｉｄｅＢｏｏｋｓ１－１１の資料のうち、右側にカラーの地図を載せてある資料に基づいてご説明をさせていただきます。\n令和７年度病児・病後児保育事業の拡充についてという資料に基づきご説明いたします。\n１、事業概要です。\n従前より、病児保育施設の地域偏在と施設数不足が課題となっておりました。その解決に向け、当初予算の１施設、こちらは以前、委員会でご報告をした南品川の施設になりますが、それに加えまして、新たに２施設を開設するための経費を補正するものです。また、利用者の利便性向上のため、施設の開所時間外でもネット上で空き状況の確認や予約ができるシステムを導入いたします。\n２番の補正の内容です。\n（１）病児保育施設新規開設です。1)の旗の台内科・救急クリニックと、2)の東京品川病院の２施設に、それぞれ定員４名の医療機関併設型の病児保育施設を開設いたします。開設に当たっての改修工事などの補助経費および運営委託費を増額補正いたします。\n（２）病児保育事業予約システムにつきましては、先ほど申し上げましたとおり、予約の利便性向上などを目的に導入するものでございます。\n（３）東京都病児保育推進事業補助金につきましては、新たな補助金、歳入の補正になります。病児保育事業の安定的な運営、新規事業者の参入促進を目的に、東京都が新たな補助金を創設しましたので、その歳入を見込むものです。こちらは既存の病児保育施設３施設、それから病後児保育施設１施設も含め、歳入を見込んでおります。\n３の歳入歳出予算は、記載のとおりになります。なお、一部減額補正を含んでおりますが、こちらは当初予算で定員８名分の経費を計上していたものを、南品川に開設する施設の定員が４名に確定しましたので、その差分の減額になります。\n４、スケジュールです。新規開設の２施設は、１１月の運営開始に向け、準備を進めてまいります。予約システムにつきましては、９月の運用開始を目指しております。\n最後に、資料の右側にお示しした地図ですが、これまで地図上の青い丸で記している３施設がございました。それぞれ目黒駅、戸越駅、荏原中延駅にありますが、区の西側に施設が偏在しておりました。そこに今回、赤い丸のうち、番号が振られていない施設、こちらが当初予算で対応する南品川の施設、それに追加いたしまして、新たに開設する赤の1)が旗の台内科・救急クリニック、2)が東京品川病院になります。\n施設数の不足に対応し、また、地域偏在の是正により、区の東側のニーズにも対応できる施設になりますので、今回の２施設、区としても積極的に開設の支援および運営をしてまいりたいと考えております。"},{"i":226,"speaker":"佐藤保育事業担当課長","text":"それでは私より、第７１号議案、令和７年度品川区一般会計補正予算のうち、とうきょうすくわくプログラム推進事業の拡充についてご説明申し上げます。ＳｉｄｅＢｏｏｋｓ１－１１、2)の資料をご覧ください。\n初めに、１番、事業概要でございます。\n子どもの豊かな心の育ちをサポートするため、令和６年度から東京都が、とうきょうすくわくプログラム推進事業を実施しております。とうきょうすくわくプログラムとは、全ての乳幼児の「伸びる・育つ」と「好奇心・探究心」を応援する幼保共通のプログラムでございます。本事業は同プログラムに基づき、乳幼児の興味・関心に応じた探究活動を実践する保育所等を支援することにより、幼児教育・保育の充実を図ることを目的としております。\n続きまして、拡充内容でございます。\n令和７年度より東京都がとうきょうすくわくプログラム推進事業の実施施設に、指導監督基準を満たす旨の証明書を有する認可外保育施設を新たに追加したため、区としても同様の取扱いとし、新規追加施設を補助対象に追加するためでございます。\n３番、歳出予算でございますが、補正額として、合計３,０００万円でございます。内訳は、１施設当たり補助上限の１５０万円に、２０園への支給を想定しているところでございます。\n続きまして、４番、歳入予算でございますが、歳出同様、３,０００万円でございます。東京都の認可外保育施設におけるとうきょうすくわくプログラム推進事業補助金を活用した、都１０分の１０の補助事業でございます。\n最後に、５番、スケジュール（予定）でございます。令和７年７月に各事業所に対して案内を行い、８月に交付申請受付開始しまして、３月に交付決定・補助金交付を予定しております。"},{"i":227,"speaker":"つる委員長","text":"説明が終わりました。\n質疑に関しましては、休憩後に行います。\n会議の運営上、暫時休憩いたします。\n○午後 ０時０２分休憩\n○午後 １時０５分再開"},{"i":228,"speaker":"つる委員長","text":"ただいまより文教委員会を再開いたします。\nこれより質疑を行います。ご質疑等がございましたら、ご発言願います。"},{"i":229,"speaker":"のだて委員","text":"補正予算の説明がありました。その中で、認可外保育施設の保育料助成の拡充をするということで、これは認証保育園も対象になるということだと思います。あと、区では、認証保育所に入っている方への補助もあると思うのですけれども、これを併せて利用すれば、無償化と同様になるのか、伺いたいと思います。\nそれと、病児・病後児保育の事業拡大ということで、今回、補正でやられるわけですけれども、補正で組むことになった理由を伺いたいと思います。"},{"i":230,"speaker":"芝野保育入園調整課長","text":"認証保育所についてのご質問をいただきました。\n認証保育所の助成は、昨年度までは、認証保育施設の保護者の補助金ということで頭出しされていたのですが、令和６年度予算から、認可外保育施設のほうに全部一緒になっておりますので、こちらが委員のおっしゃられる補助金かと思われます。\n無償化になるかどうかというところでございますが、認可保育園につきましては、今回無償化が達成されるということで、認可外保育施設のほうも認可保育所と同水準までの助成、こちらが想定で８万円を考えているのですが、こちらまで引き上げることによって、無償化に近い形で達成されるということで東京都は考えているようでございます。"},{"i":231,"speaker":"染谷保育施設運営課長","text":"病児保育の開設につきまして、補正予算をご提案した理由でございますけれども、当初予算につきましては、例年１施設分の予算を計上してございます。実際に開設のめどが立たない場合については、最終補正で減額をするといった対応をしている中でございますが、先日の文教委員会でもご報告申し上げたとおり、南品川の１件、施設開設のめどが立っております。\nそれに加えて昨年度から、今回補正の対象とさせていただいている２施設について、交渉、協議を進めている中で、今回、開設のめどが立ったというところで、以前から地域偏在ですとか施設の不足というのが課題になっておりましたので、できるだけ早く開設をしたいというところで、今回補正を出させていただいているというものになります。"},{"i":232,"speaker":"のだて委員","text":"分かりました。病児・病後児保育は、今なかなか保護者の方も仕事を休めないとか、そうしたことがある中で、病気になった子を預ける場所があるというのは、利用者にはすごく助かると思うのですけれども、本来あるべき姿というのは、子どもが病気になったときに、子どもを見てあげられる、仕事を休むことができるという社会環境をつくっていくということが、子どもにとっても保護者にとってもいいことだと思いますけれども、区のお考えを伺いたいと思います。"},{"i":233,"speaker":"染谷保育施設運営課長","text":"お子さんが実際に病気のときに、ふだん一緒にいる保護者、お父さんお母さんと一緒にいられるというのが一番いいというのは、間違いないことだと思っております。実際にそういったところを、いろいろご家庭の事情ですとか就労の関係がある中で、お仕事を休めない、勤務せざるを得ないという状況がある中では、専門職、保育士ですとか看護師が実際にお子さんの保育をしていると。そういった体制というのは、区として責任を持って整備していく必要があると考えているところでございます。"},{"i":234,"speaker":"のだて委員","text":"ぜひ区としても、保護者の方が仕事を休んで子どもを見られるという環境整備に力を尽くしていただきたいと思います。"},{"i":235,"speaker":"つる委員長","text":"ほかにございますか。"},{"i":236,"speaker":"横山委員","text":"私からは、病児保育のところをお聞きしたいと思うのですけれども、先ほど２の補正内容の（３）でご説明あったのですが、少し聞き漏らした部分がありまして、７施設とありますが、病児保育施設が６施設と、病後児保育が１施設ということになるのでしょうか。この辺が少し分からなかったので、もう一度ご説明をいただけたらと思っております。\nまた、予約システムはすばらしいと思っているところなのですけれども、９月運用開始ということで、まずは３施設から始めるということなのでしょうか。新規開設の施設の残りの３施設は１１月に運用開始ということで、時期としてはよろしいのでしょうか。\nまた、こちらの予約システムは、病児保育のみということなのでしょうか。病後児のところと併せてなのか、もう少し教えていただけたらと思います。病児保育のみで予約のシステムを登録していただいて、そこで例えば前日までとかに予約をすると、予約ができるという内容、そういったイメージでよろしいのか、実際のイメージのところも教えていただけたらと思います。"},{"i":237,"speaker":"染谷保育施設運営課長","text":"まず、（３）の東京都の新設された補助金の対象でございますけれども、委員おっしゃるとおりで、病児保育施設につきましては、新規のものを含めて６施設分、それから病後児保育につきましては、現状、区立の保育園３園と、それから私立の保育園１園で実施しております。区立については補助金の対象になりませんので、残りの１施設分が病後児保育施設として、補助の対象になるというものになっております。なので、トータルで病児・病後児合わせて７施設という考え方でございます。\nそれから、システムにつきましては、病後児保育につきましても、こちらは公立の部分も含めてですけれども、対象となるように現状準備を進めているところでございまして、当初予算で対応を予定している南品川につきましても、開設は今、９月１日を予定しておりますので、今回補正でお願いをさせていただいている２施設以外は、システムの導入と併せて実施をしていきたいと考えておりますけれども、こちらについては、病児保育を運営されている各法人のご意見だとか、いろいろお聞きしながらなので、全ての施設について一斉に９月１日というようなスタートではないということも、十分に想定されると考えております。\nそれからあと、システムイメージですけれども、これまで電話で予約をすると。その前に受診をして、その状況によって電話で予約を入れて、翌日行くというようなイメージだったのですけれども、そこの部分をＬＩＮＥなど活用して、当然、前日に受診はしていただく必要があるのですが、ＬＩＮＥ上に受診した医師連絡票をオンラインでアップロードして、ＬＩＮＥ上ですとかオンライン上で予約を入れられるというシステムの運用を、今想定しているところです。"},{"i":238,"speaker":"つる委員長","text":"ほかにございますか。"},{"i":239,"speaker":"まつざわ委員","text":"病児・病後児保育で、要は、地域偏在と施設が不足しているというので増やしたわけです。そうすると、増やしたときに、品川区全体のバランスを見て、区としてこれで取りあえず落ち着いたと考えるのか、まだまだ足りないと考えるのか、まず教えてください。"},{"i":240,"speaker":"染谷保育施設運営課長","text":"まず、病児保育の需給状況につきましては、現状、こども計画で試算をしているといいますか、計画している需要と供給の数の部分につきましては、今回の２施設を追加することによって、十分需要は満たせるかなと考えております。\n地域偏在の部分につきましても、今回、東側にも施設を開設しますので、一定程度、そちらについても是正されるものと考えているところです。"},{"i":241,"speaker":"まつざわ委員","text":"そうしますと、ある程度落ち着いたというか、区としてはそういう考えがあるわけです。そうすると、病後児保育・病児保育は日中が主なのですけれども、例えば早朝とか夜間の利用の声は、非常に根強くあるわけです。そうすると、結局、これが一回、計画の中である程度数が落ち着いたという部分があれば、そういった、課題が多いのは十分分かっているので、早朝とか夜間の利用というのも、これから考えていかなければいけないという部分もあるのです。その辺の考え方というのは。"},{"i":242,"speaker":"染谷保育施設運営課長","text":"病児保育で早朝・夜間のご利用の枠の考え方でございますけれども、これまでもいろいろと区民の方から、病児保育に関するニーズ、お声をいただいているところもございますので、そういったお声をきちんとお聴きする中で、必要性について検討させていただければと考えております。"},{"i":243,"speaker":"まつざわ委員","text":"そうしたら次に、ベビーシッター利用助成なのですけれども、ベビーシッター利用助成は助成が増えたということは大変うれしいことであります。その中で、うちの会派のせお議員からお話してほしいというので、要は、障害児の利用助成が増えるということは、それだけ需要があるということに関して、ベビーシッターの方の、例えば障害児、見られますという人の需要と供給というのが、相互性というのは取れるのかというのを聞かせてください。"},{"i":244,"speaker":"芝野保育入園調整課長","text":"ベビーシッターのご質問をいただきました。障害児の方を見るベビーシッターの方の需要と供給のバランスが取れるかというご質問でございますが、ベビーシッターの利用支援事業は、登録制といいますか、事業者を認定して、そちらの事業者がこのような形で、障害児もしくはひとり親という形のお子さんをお預かりできるかどうかの判断をして、実際にお宅に訪問するという形になっておりまして、現状では、ベビーシッターの育成もずっと東京都が進めておりますので、バランスは取れているのかなと。\nただし、この事業が拡充されることによって、また不足するような事態がございましたら、そちらは東京都と連携を取りながら、情報も収集しながら、何か施策が取れるかどうかというのは検討していきたいと考えております。"},{"i":245,"speaker":"まつざわ委員","text":"ぜひ、せっかく増えるような見込みがあると思うので、区でも地域の保育士とか、看護資格を持っている人たちの再活用とか研修とか、そういうのはどんどんやっていっていただきたいと思っています。\nあと１つ、最後にスケジュールなのですけれども、これが始まるのが令和７年７月です。でも、実際は令和７年の４月利用分より適用ということは、結局、過去に戻ってやるわけです。そうすると、周知が結構大事なのかなと思ったのです。過去まで遡らなければいけないので。そうすると、いわゆる情報弱者という方は、障害児の家庭であったり、ひとり親であったりというのが、なかなか情報リテラシーに乏しいというところもあったりするので、例えばその辺に特化した周知というのは何か考えているのか教えてください。"},{"i":246,"speaker":"芝野保育入園調整課長","text":"今回のベビーシッターのスケジュール案の周知のことでございますが、４月利用分まで遡って申請を受け付けるということで、四半期ごとに申請を行っておりますので、その際に、こういう事業をしっかりやっていますという周知をさせていただきたいと考えております。"},{"i":247,"speaker":"まつざわ委員","text":"四半期ごとにやっているから、今度のものはいいけれども、前の分も改めて、こうやって周知はしてくれるということですか。"},{"i":248,"speaker":"芝野保育入園調整課長","text":"すみません、言葉が足りませんでした。４月からしっかりとやっていますということを周知して、４月に遡って申請を受け付けさせていただきたいと考えております。"},{"i":249,"speaker":"つる委員長","text":"ほかにございますか。"},{"i":250,"speaker":"若林委員","text":"補正を外れるところがあるかもしれませんけれども、質問をさせていただきます。\nまず、東京都の病児保育推進事業が今年度ありまして、２つ、施設型の事業者への支援と、ベビーシッター事業者への支援を行うことになっています。\n施設型事業者支援については、経営の安定性を確保して、事業者の新規参入を後押しするという国事業の上乗せとして、東京都が基本分の単価のかさ上げを示している。また一方で、ベビーシッターについては、既存の一時預かり事業では対応可能な事業者が幼児を預かることもあったのだけれども、今回、都は検証事業として、質とか安全性、派遣体制を確保した認定事業者に対して、１時間当たりの補助基本額を大幅に増額し、支払いも都が直接事業者に行うなど、事業者と利用者双方にとって拡充された事業を、東京都が今年度行っているという、東京都の事業ですけれども、これを受けて、施設型の病児保育の施設については、今年度早期に開設を区に対して要望するということが１つあります。それからもう１つは、病児対応型の基本分単価のかさ上げについても、区で活用していただきたい。またもう１つ、ベビーシッターを利用した病児保育に係る研修事業を、これも区において実施していただきたい。\nこういった３点を、実は５月８日に公明党会派から区長に申入れしたという経緯があります。この３点について、少し外れるところがあるかもしれませんけれども、この場をお借りして、その後の進捗状況をお聞きしたいと思うのが１つでございます。\nそれから、認可外保育園の助成については、月額８万円とか、３歳以上は７万７,０００円を上限というところで、現状、認可外・認証保育の１か月の保育料の一番低いところとか、逆に一番高いところとかという数値はどのように捉えられているか、お聞きしたいと思います。\nまた、都の補助金ですけれども、区も一部入れてやっていますが、補助金が上がったことで事業者が、過去によくあった話として、補助金が上がったので、事業所の保育料を上げるという動きがあったとしたら、それに対して区は何か手だてを考えておられるのかというのも、２つ目にお聞きしたいと思います。\nそれから、すくわくプログラムについては、約半数の園がすくわくプログラムの、区が今回やる補助事業に対して手を挙げるだろうという予測をされて、今回の補正予算が組まれていると読み取っておりますけれども、認可保育で既に当然やられているわけですが、その辺の何かすくわくプログラムの成果とか課題とかがあったら、お聞かせいただきたいと思います。"},{"i":251,"speaker":"染谷保育施設運営課長","text":"１点目、早期開設の部分でございますけれども、こちらについては、補正予算が議決をいただけた場合については、速やかに準備を進めてまいりまして、先ほどお示ししたスケジュールのとおり実施をしていきたいと。それに併せて、東京都病児保育推進事業、都の補助金を貴重な財源としてしっかり活用させていただいて、進めていければと考えております。\nまた、委員から今お話しいただいたとおり、既存の病児保育施設についても、基本単価にかさ上げがされるという、東京都の高い補助率で今回補助が新設されたということもありますので、今後きちんと既存の施設についても申請をして、そういった貴重な財源をしっかりと獲得して、事業を進められればと考えているところです。"},{"i":252,"speaker":"芝野保育入園調整課長","text":"私からは、ベビーシッターを利用した病児保育に係る検証事業の今の状況をご説明させていただきたいと思います。\n本事業は、突発的な病気などで保育所への預け入れが難しい未就学児の保護者が、東京都の認定を受けた事業者を利用した場合、利用料の補助基準額が大幅に拡充されるという事業になります。現在、事業者の決定とか、あと事業開始時期については、明確な時期というのは示されておりませんで、今、都の担当部署と情報共有をしっかり行っている状況であります。\n現在、都によると、事業者の募集とか、研修の実施とか、事業者の認定はまだ進んでおらず、それが進み次第、区に対して実施要綱というのを発出して、事業が開始になるということで、区もそれに合わせて速やかに実施していきたいと考えております。\n引き続き、認可外保育施設のことでございます。認証保育所、認可外保育施設の最高額、最低額ということでございますが、申し訳ございませんが、詳しい金額までは把握していないところでありますが、認証保育所の最高額は規定で決まっておりまして、８万円になっておりますので、認証保育所については無償化がされるという状況になっております。\n最後に、補助金の今回の値上げによって、事業者がどのような動き、値上げをするのかというところでございますが、認可外保育施設でございますので、保育料を決めるのは認可外保育施設の自由といいますか、裁量の中でやっていくものでございますが、利用者の不利益にならないように、しっかり監視して、そういうお声を聞いた場合には、しっかり事業者の方に話をお聞きして対応していきたいと考えております。"},{"i":253,"speaker":"佐藤保育事業担当課長","text":"私からは、すくわくプログラムの成果についてご回答させていただきます。\n昨年度、区立を含めまして７０を超える施設で、本プログラムを実施してございます。その中の成果といたしまして、まず、子どもたちに関しては、自らの興味に応じて様々な活動をすることで、子どもたちの関心が広まって、日々の活動が活発になったというお声を聞いてございます。\nまた、保育所にとりましても、ふだんの保育の中では見られなかった子どもたちの興味・関心に気づくことができるなど、新たな発見があったと聞いており、子どもへの関わり方を知る機会になったという声をいただいております。\n加えまして、プログラムの検討などをすることで、保育者間の連携というのも強化されたというお声も聞いております。"},{"i":254,"speaker":"つる委員長","text":"ほかにございますか。よろしいですか。\n１点だけ。病児・病後児のシステムの関係に関連してなのですが、これまでの利用者の流れの中で、それぞれ施設で、クリニックと併設しているところと提携というところで、そのまま診察全部、そういう流れは大きくは変わらないだろうと思います。\n今の現実の様々なご相談だとかも含めて、先ほどほかの委員からもあって、施設自体は増えている、計画どおりいくというのがあるのですが、利用者側の使い勝手というか、要は、各施設の情報提供しているホームページ等で出ている情報と、予約システムを経由してというか、予約システム上にある情報ないし経由する情報の、ラグがないようにしないといけないというのは感じます。\n当然それぞれの施設で受け入れられる、受け入れられないという大前提があったりすると思うのです。そういったところもありますし、それを含めたシステムの予約の段だと思うのです。システム自体は予約なのだけれども、情報の確認のときの情報が、差が出てしまわないような仕組みにできるのかというところとか、どのような連携を取るのかというところ、その辺りについて教えていただければと思います。"},{"i":255,"speaker":"染谷保育施設運営課長","text":"委員長おっしゃるとおりで、大きく流れは変わらず、引き続き、各病児保育の施設に登録をいただいて、登録をいただいた上での予約の段で、これまでクリニックが実際に開所している時間帯での電話の予約が、システムに置き換わるというイメージになるかと思います。\nタイムラグというお話がございまして、その点についてはきちんと対応できるような仕組みにはなっているのですけれども、基本的には、前日までのオンライン上での予約について、翌朝、各病児保育のほうでその予約状況を確認して、当然その中で、病状によっても、同時に受入れできないお子さんなどもいるかと思いますので、そういったところをきちんと確認した上で、最終的な予約の確定という流れになりますので、基本的にはタイムラグといったものは発生しないような仕組みで運営をできるのではと考えているところです。"},{"i":256,"speaker":"つる委員長","text":"そもそもの施設によって、あくまでもこれは病児、病なのだけれども、特定疾病というか、いろいろな難病等々を含めて、ドクターの見地からすると、うちの施設では難しいという施設も既存であるのだと思うのです。そうしたところの情報が、こういうシステムを含めてきちんと利用者、利用したい人が分かるようなこと、それが今まで以上に、より精度が上がるような形でやっていく必要があるというところと、先ほど若林委員からあった東京都の検証事業を活用して進むというところと、より様々な病児保育が進むという全体の中では、所管は今、この委員会ではそれぞれの担当の課長がお答えいただくような、まさに中の人としてはそういう対応なのですが、利用する側からすれば、病児保育としての利用で、お願いする事業者が施設なのか、ベビーシッターなのかという違いはあるのだと思うのですが、その辺が分かりやすいような形での、まさに情報提供も必要だというところで、これまでもやっていただいていると思うのですけれども、区としての情報の出し方とか、その辺も今まで以上に工夫をやっていただきたいと要望させていただきます。\nほかによろしいでしょうか。\nほかにご発言がないようですので、これで質疑を終了いたします。\n採決に入ります前に、第７１号議案、令和７年度品川区一般会計補正予算（歳出 文教委員会所管分）につきまして、各会派の態度を確認いたします。\nそれでは、品川区議会自民党・無所属の会からお願いいたします。"},{"i":257,"speaker":"まつざわ委員","text":"賛成です。"},{"i":258,"speaker":"筒井副委員長","text":"賛成です。"},{"i":259,"speaker":"若林委員","text":"賛成です。"},{"i":260,"speaker":"のだて委員","text":"保護者の負担軽減につながるものなので、賛成です。"},{"i":261,"speaker":"高橋（し）委員","text":"賛成です。"},{"i":262,"speaker":"横山委員","text":"賛成です。"},{"i":263,"speaker":"つる委員長","text":"それではこれより、第７１号議案、令和７年度品川区一般会計補正予算（歳出 文教委員会所管分）について、採決いたします。\nお諮りいたします。\n本案は、原案のとおり決定することにご異議ありませんか。\n〔「異議なし」と呼ぶ者あり〕"},{"i":264,"speaker":"つる委員長","text":"ご異議なしと認めます。よって、本案は全会一致で原案のとおり可決決定いたしました。\n以上で、議案審査を終了いたします。\n────────────────────────────────────────────\n２ 請願・陳情審査\n令和７年陳情第２０号 「税負担化」を「無償化」とミスリードする公立学校の制服無償化事業の廃止及び、住民税の減税を求める陳情"},{"i":265,"speaker":"つる委員長","text":"次に、予定表２、請願・陳情審査を行います。\nそれでは、令和７年陳情第２０号、「税負担化」を「無償化」とミスリードする公立学校の制服無償化事業の廃止及び、住民税の減税を求める陳情を議題に供します。\nまず、本陳情は初めての審査でありますので、書記に朗読させます。\n〔書記朗読〕"},{"i":266,"speaker":"つる委員長","text":"朗読が終わりました。\nそれでは、本件につきまして、理事者よりご説明願います。"},{"i":267,"speaker":"石井学務課長","text":"それでは私から、令和７年陳情第２０号、「税負担化」を「無償化」とミスリードする公立学校の制服無償化事業の廃止及び、住民税の減税を求める陳情についてご説明申し上げます。\nなお、減税の是非についてではなく、当課の立場として、標準服無償化事業のご説明をさせていただきたいと存じます。\n標準服無償化事業につきましては、保護者に対して標準服を無償化するということにより、その経済的負担の軽減を図ることで、児童・生徒の円滑な学校生活を実現することを目的としてございます。\n区では、誰もが共通に使う日常的生活を支える基礎的な行政サービスを等しく提供する、ベーシックサービスという考え方の下、各種無償化事業を展開しております。これは、決してばらまきということではなく、共通のリスクに対する共通の備えを保障する、これを社会全体で負担していくという、言わば社会保障システムの一環であると考えております。\nなお、教育につきましては、本来、国の責任において全国一律で無償で行われるべきものと考えておりますけれども、その中で、誰もが等しく、かつ不安なく教育を受けられるよう、これまでも学校におきましては、給食費ですとか補助教材について無償化をしてまいりました。本年度は、その中でも特に負担が大きいとされている中学校進学時の標準服購入費用について、所得に関わらず無償化するものでございます。\n現在その方法につきまして、先般、予算特別委員会でご審議いただいた際にご提案のありましたクーポン方式ですとか、そういったことも含めて、検討を進めている段階でございます。"},{"i":268,"speaker":"つる委員長","text":"説明が終わりました。\nこれより質疑を行います。ご質疑等がございましたら、ご発言願います。"},{"i":269,"speaker":"のだて委員","text":"まず、制服無償化をやめて住民税減税をということですけれども、実際、住民税を減税すると、１人当たり幾らになるのかというのは計算されているのか伺います。"},{"i":270,"speaker":"つる委員長","text":"さっき冒頭あったとおり、その部分については所管外なので、持ち合わせはないという前提で質疑をしたいと思いますので、その上で、今の質問に対して何か答弁があればお願いします。"},{"i":271,"speaker":"石井学務課長","text":"詳しい数字そのものについては、実際の実績等、恐らく税務課が所管で持っているものでございます。なので、例えば一般論として、今回令和５年度決算書に書かれている数字でございますけれども、納税義務者をざっと計算しますと、約２７万人いらっしゃって、その金額に、例えば均等割が３,０００円とか、そういったことを掛けると、大体８億円ぐらい。その８億円の中で、この金額ですると、約１億円の金額で約８分の１、それを人数で割っていくとどれほどの減税になるかということに、計算としてはなろうかと思っております。\nただ、私のほうで詳細に試算しているわけではないので、この場で何か申し上げるものではございませんけれども、簡単な推計ですと、そういったことが可能ではないかと考えております。"},{"i":272,"speaker":"のだて委員","text":"私も試算をしてみまして、大体、住民税負担世帯の中で２４.２％が非課税世帯ということで、課税世帯がそうすると７５.８％、品川区の世帯が２４万世帯なので、それを掛け合わせると１８万２,４００世帯ということで、制服の無償化が１億１４２万円余と。そこで割り返すと、世帯当たり５５６円、月にしたら４６円、減税のために使えるという感じではあるのですけれども、子育て世帯でなくても、月４６円ではあまりにも現状から言えば少な過ぎると思いますので、そうした考えではなくて、今、負担軽減という意味では、消費税が一番重い税金になっておりますので、消費税の減税こそ必要だと思います。年収８００万円のところまで、一番重いのは消費税ということになりますので、そうしたところにこそ目を向けるべきではないかと思います。\n税の負担の考え方なのですけれども、私は税金というのは、所得のある人が支払い能力に応じて納めてもらう。それを、低所得者の人でも医療や介護などを受けられるようにする。それが所得の再分配であり、社会保障なのだと思います。自分たちに必ず恩恵が来るというものではないというものだと思うので、全体的な、区民全体に対して社会保障を提供していく、所得を再分配していくというのが税金の考え方だと思います。物価高で暮らしが大変なので、負担を下げてほしいという思いは分かりますけれども、考え方が少し違うのではないかと思います。\n陳情の中には、制服の無償化で、制服の必要性が固定化されるということも書かれておりますけれども、私は別に、無償化と制服の必要性というのは別問題だと思います。実際、制服の無償化、なくす方向であれば、なくす方向で、別の問題として考えていくことが必要と思います。\n実際、無償化すると、制服をなくすことができないのかというのを区に伺いたいと思います。"},{"i":273,"speaker":"石井学務課長","text":"おっしゃるとおり、無償化の問題と、制服そのものをやめるというのは、別の議論になってくると考えてございます。その上でですけれども、例えば制服の必要性そのものについては、生徒の中で、そもそも制服は必要なのかとか、そういったことを議論するということは十分可能であると思っておりますが、逆に言うと、今度その考え方に基づくと、一律に必要だという考え方に対して、一律に不要だという考え方もまた違うのではないかと。様々な選択肢がある中で、きちんと制服の在り方について考えていくことが必要と考えております。"},{"i":274,"speaker":"のだて委員","text":"制服の無償化と必要性については、別問題だということでした。選択肢もいろいろあるということでしたけれども、私は小学生はどんどん成長してしまうので、制服が大きなものが必要になってくる、買換えも必要になってくるということになるので、小学生段階では必要ないと思いますけれども、いろいろ選択肢があることが重要だというお話もありましたので、そこは生徒の皆さん、あるいは地域の皆さんがぜひ議論して、その必要性については考えていけばいいのかなと思います。\n制服の無償化がなぜ必要かといえば、やはり制服の負担が重いということです。制服だけではなくて、いろいろほかにワイシャツとか、ブラウスとか、体操着とか、靴もそうです。いろいろ負担をする中で、全体を合わせれば１０万円程度になってくるということになる。それを無償化していこうというものだと思いますので、私は必要なことだと思います。区も引き合いに出していますけれども、憲法第２６条の義務教育の無償化、これを実現していく第一歩ということだと思いますので、私はぜひ必要なものだと思っております。\n陳情の中で、制服によって貧富の差が解決するものではないということも言われておりますけれども、それはそのとおりだと思いますが、低所得の人ほど負担が重いというのもそのとおり、だからこそ無償化が必要なのだと私は思います。無償化で貧富の差が解決すると思っている職員の方もいないと思います。やはり問題は、貧富の差を大本から変えていくと。先ほども言いました大企業や富裕層に支払い能力に応じた負担をしてもらって、消費税の減税をやっていくこととか、また、最低賃金を引き上げて給料を上げていくということなどを行って、根本的に元から変えていくことが私は必要だと思います。"},{"i":275,"speaker":"つる委員長","text":"ほかにございますか。よろしいですか。"},{"i":276,"speaker":"筒井副委員長","text":"確認を含めて、現在、品川区の学校では生徒全員が制服を着ているのかということと、あと、制服の教育的効果というのはどのようにお考えなのでしょうか。"},{"i":277,"speaker":"石井学務課長","text":"まず、品川区全体なのですけれども、中学校においては標準服着用となっており、義務教育学校につきましては１年生から４年生、そして５年生以降ということで、それぞれ標準服を着ておりますけれども、学校によっては標準服を着ていないところもございますし、あとは着ていないからといって、学校に入れないとか、そういったことはないようにしているところでございます。\nまた、教育的な効果の部分につきまして、私が教育的効果についてそこまで言及するのは難しいのですけれども、令和７年の予算特別委員会の議論の中では、教育的な効果の部分としては、例えば教育環境を整えることですとか、生徒の安全の確保、これは例えば教室の内外とかで服装によって見分けることができるとか、あとは、節約や簡便さですとか、そういったことの醸成ですとか、毎日の服装にかかるコストとか手間の軽減というものは、結果として家計負担の軽減につながるというところで、直接・間接にいろいろな効果が見込まれると考えているところでご議論いただいたところでございます。"},{"i":278,"speaker":"筒井副委員長","text":"また、今回、無償化といっても、クーポンを支給するということで、要は現金を渡してという形ではないのですよね。その確認です。"},{"i":279,"speaker":"石井学務課長","text":"現在考えているクーポン方式なのですけれども、例えば現金とか商品券とか、そういった類いではなくて、制服の現物のための制服引換券のような、そういったイメージを持ったクーポンで考えているところです。また、紙クーポンではなく電子クーポンの導入ができないかということで、現在、事業者と詳細を詰めているところでございます。"},{"i":280,"speaker":"つる委員長","text":"ほかにございますでしょうか。"},{"i":281,"speaker":"若林委員","text":"公明党会派からも、ベーシックサービスの観点で様々な申入れを本会議や予算・決算特別委員会で議論させていただいて、令和７年度においては、標準服の無償化というものの議論を、お互いの納得の中で進めさせていただいたという、まず経緯、大前提がございます。\nですので、この税負担化とか無償化とか、言葉遊びみたいにしか私は聞こえないので、本会議場でも議論が、私は聞いていましたけれども、どうしてもかみ合わないというか、このように言い換える意味が私は全然分からなかったので、その議論は割愛しますけれども、前期の２４年度の参考までに、これは別に理事者に聞くとかという問題ではないのです。\n前年度、私は厚生委員会におりまして、この陳情の提出者が厚生委員会に２回、請願と陳情という形で住民税の減税を求める陳情を出してきました。文教委員会には標準服の無償化ということなのですが、そのときは、厚生委員会では長寿お祝い事業を廃止して、それをもって減税しろと。こういう請願・陳情があって、各会派議員から、それは全く次元の違う話でしょうということで、若干の賛成者はいらっしゃいましたけれども、ほぼ全会一致みたいな形で否決をされた。\nトレードオフみたいな形で減税を求めてくるというのは、今回は標準服の無償化というのが１つのターゲットにされたみたいで、言葉が過ぎるかもしれませんけれども、私は非常に不愉快で、だから減税を求めるのに、トレードオフの対象の事業は何でもいいのではないかと、私は厚生委員会と文教委員会の２つに参加して、そのように感じていますので、こういうトレードオフみたいな形で住民税の減税というすごく大きな問題を陳情して、委員会で議論してくれというのは、私はとても賛成することは、その内容についても、やり方についても、うなずけるものではないということは、委員の皆さんにも紹介させていただきたいという意味で発言をさせていただきました。"},{"i":282,"speaker":"つる委員長","text":"ほかにございますか。よろしいですか。\nほかにご発言がないようですので、これで質疑を終了いたします。\nそれでは、令和７年陳情第２０号の取扱いについてご意見を伺いたいと思います。\n継続にする、あるいは結論を出す、どちらかご発言願います。また、結論を出すのであれば、その結論についてもご発言ください。\nそれでは、品川区議会自民党・無所属の会からお願いいたします。"},{"i":283,"speaker":"まつざわ委員","text":"結論を出すで、不採択です。理由は、願意に沿い難い。"},{"i":284,"speaker":"筒井副委員長","text":"本日結論を出すで、不採択でお願いします。\n理由は、今回の陳情者の方の思いは、私のさきの一般質問でも述べさせていただきましたとおり、現役世代を中心に、物価高騰の一方、給与は上がらず、生活は苦しいという背景があるかと思います。その中で、税の使われ方に対して非常に厳しい見方をされる方が増えてきている。この方も含めて、そうだと考えております。また、無償化といっても、それは税で負担されているということ、税負担化でこういう事業が成り立っているという意識は非常に必要と考えております。\nしかし一方、今回に限っては、制服無償化事業を廃止して住民税減税ということなので、私としては住民税減税については、一律公正な支援策として必要かなと思っておりますけれども、今回の制服無償化事業を廃止してということになりますと、今回の制服無償化事業というのは新規事業であるということで、事業の効果を見る必要もありますし、また、減税の効果も少ないという理由で、今回の陳情については不採択でお願いします。"},{"i":285,"speaker":"若林委員","text":"結論を出すで、不採択です。"},{"i":286,"speaker":"のだて委員","text":"結論を出すということで、制服無償化は必要だと思いますので、不採択です。"},{"i":287,"speaker":"高橋（し）委員","text":"結論を出すで、不採択です。理由は、学務課長のお話等を伺って、それで理解しましたので。"},{"i":288,"speaker":"横山委員","text":"結論を出すで、不採択でお願いいたします。先ほどの質疑を伺いまして、子育て・教育に係る経済的負担の軽減は大切だと考えますので、よろしくお願いいたします。"},{"i":289,"speaker":"つる委員長","text":"それでは、本陳情については、結論を出すとのご意見でまとまったようでございますので、そのような取扱いでよろしいでしょうか。\n〔「はい」と呼ぶ者あり〕"},{"i":290,"speaker":"つる委員長","text":"それでは、本件は、本日結論を出すことに決定いたしました。\n先ほど、それぞれの方のご意見を伺いましたので、本陳情については、簡易採決により、採決を行います。\nそれでは、令和７年陳情第２０号、「税負担化」を「無償化」とミスリードする公立学校の制服無償化事業の廃止及び、住民税の減税を求める陳情について、お諮りいたします。\n本件を不採択とすることにご異議ありませんか。\n〔「異議なし」と呼ぶ者あり〕"},{"i":291,"speaker":"つる委員長","text":"ご異議なしと認めます。よって、本件は不採択と決定いたしました。\n以上で本件を終了いたします。\n────────────────────────────────────────────\n３ 報告事項\n(1) 専決処分の報告について（報告第２５号）\n(2) 専決処分の報告について（報告第２６号）"},{"i":292,"speaker":"つる委員長","text":"次に、予定表３の報告事項を聴取いたします。\n(1)専決処分の報告について（報告第２５号）および(2)専決処分の報告について（報告第２６号）を一括して議題に供します。\n本件につきまして、理事者よりご説明願います。"},{"i":293,"speaker":"丸谷教育総合支援センター長","text":"それでは私から、専決処分の報告について、報告第２５号および報告第２６号を一括して説明いたします。\n初めに、報告第２５号の資料をご用意いただければと存じます。\n本件は、地方自治法第１８０条第１項の規定による議会の指定議決に基づき、自動二輪車走行中に起きた乗用車への追突事故について、令和７年２月５日に専決処分をいたしましたので、同条第２項の規定に基づき報告するものでございます。\n資料の項番２、事故の概要でございます。令和６年９月１１日、教育総合支援センターの職員が運転する自動二輪車が、品川区戸越５丁目１番先の路上で停車していた際、手元の操作を誤り発進したため、前方に停車中の乗用車に追突し、同車の左後部バンパー等を破損したものでございます。\n損害賠償額および事故の相手方については、報告書に記載のとおりです。\n続いて、報告第２６号について説明いたします。資料をご用意いただければと存じます。\n本件は、同じく地方自治法第１８０条第１項の規定による議会の指定議決に基づき、庁用車運転中に起きた塀の破損事故について、令和７年２月１２日に専決処分をいたしましたので、同条第２項の規定に基づき報告するものでございます。\n資料項番２、事故の概要でございます。令和６年１０月３０日、教育総合支援センターの職員が運転する庁用車が、品川区大井のマンションの駐車場から路上に出る際、右方の安全確認を怠ったため、当該駐車場の塀に接触し、その一部を破損したものでございます。\n損害賠償額および相手方については、報告書に記載のとおりです。\n２件ともに、教育総合支援センターの職員の不注意による事故でございます。事故を起こした職員には十分指導するとともに、所属職員に対しても、自転車の運転も含め、交通ルールを遵守することなど、安全への配慮について繰り返し周知徹底してまいります。\nこのたびは申し訳ございませんでした。"},{"i":294,"speaker":"つる委員長","text":"説明が終わりました。ご質疑等がございましたら、ご発言願います。"},{"i":295,"speaker":"高橋（し）委員","text":"２５号のほうなのですけれども、自動二輪車というのは、いわゆるバッテリーがついている自転車なのでしょうか。それは教育総合支援センターの庁有自転車なのでしょうかということをまずお尋ねします。"},{"i":296,"speaker":"丸谷教育総合支援センター長","text":"こちらの自動二輪車についてですけれども、原動付自転車ということで、いわゆるスクーターのようなものでございます。教育総合支援センターが所有している庁有車でございます。"},{"i":297,"speaker":"高橋（し）委員","text":"ということは、それで勤務中にこういったことを起こしたので、区の責任で賠償したということでよろしいですか。"},{"i":298,"speaker":"丸谷教育総合支援センター長","text":"おっしゃるとおり、勤務中の事故でございます。"},{"i":299,"speaker":"つる委員長","text":"ほかにございますか。\n〔「なし」と呼ぶ者あり〕"},{"i":300,"speaker":"つる委員長","text":"ほかにご発言がないようですので、以上で本件および報告事項を終了いたします。\n────────────────────────────────────────────\n４ その他"},{"i":301,"speaker":"つる委員長","text":"最後に、予定表４、その他を議題に供します。\nまず、今定例会の一般質問に関わる所管質問ですが、今定例会の一般質問中、文教委員会に関わる項目について、所管質問をなさりたい委員がいらっしゃいましたら、その基礎となる一般質問の項目と、質問内容をこの場でお願いしたいと思います。なお、本会議場での質問の繰り返しにならないようにお願いいたします。\n質問される委員がいらっしゃる場合は、明日、この委員会で理事者からご答弁をいただき、申し出た委員以外の方にも議論に加わっていただくという形で進めていきたいと思います。\nそれでは、所管質問がございましたら、ご発言願います。"},{"i":302,"speaker":"高橋（し）委員","text":"これはお尋ねしたいのですけれども、特別委員会ができて、所管が分かれたのですが、例えば、これを質問するという意味ではないのですけれども、５歳児健診のところで、保育園・幼稚園のいわゆる巡回相談のお話が出てきたのですが、そのことをこの委員会で所管質問してもいいのですか。しないのですけれども、所管的にはいいのですか。"},{"i":303,"speaker":"つる委員長","text":"５歳児の健診の巡回相談ですか。"},{"i":304,"speaker":"高橋（し）委員","text":"はい。保育園のことだから。"},{"i":305,"speaker":"つる委員長","text":"在り方。"},{"i":306,"speaker":"高橋（し）委員","text":"在り方になってしまうから、あちらになってしまうのですかということを。"},{"i":307,"speaker":"つる委員長","text":"すみません、事務的なところも含めてですけれども、書記にも確認させていただいて、こちらで質疑するようになっていますので、そこも含めて。"},{"i":308,"speaker":"高橋（し）委員","text":"巡回相談については置いておいて、横山委員が児童相談所の一時保護のことを質問されたのですけれども、そのときに、定員を上回る状況が続いているという話があって、ここの委員会でも最初に少しご説明いただいたのですけれども、そのときの答弁で、組織的に対応するようにいろいろというお話があったのです。\nそれで、もしかしたらここの所管ではないのかもしれませんけれども、事務的な対応とか、あと２３区で協力してとか、そういうところはいろいろお話が出てきたのですが、前に私が一般質問でお尋ねした、都立児童相談所が移転するので、そこをというお話をしたことがあって、それは企画のお話になってしまうかもしれませんけれども、そういうことを含めて、児童相談所として、区の中の所管に、今、一時保護がこういう状態だから、このようにしてほしいというような働きかけを、しているかいないかということはここで聞いてもいいのですか。"},{"i":309,"speaker":"つる委員長","text":"先ほど冒頭あった質問の内容に関しても、要するに重ならないというところと、それに関する議論ということですので、それは問題ないということです。"},{"i":310,"speaker":"高橋（し）委員","text":"ということで、大変な状況の中で一時保護がやられているということは認識していますので、それを解決するために、区の中の他セクションにこういう体制をということで働きかけていただきたいと思っているので、そういうのをしていただけているかどうかというのをお尋ねしたいと思います。答えられる範囲で、担当部署がどういう対応をしているのかということをお答えいただければと思います。"},{"i":311,"speaker":"つる委員長","text":"ほかにいらっしゃいますか。よろしいですか。\nそれでは、今の高橋しんじ委員からの所管質問に関する質問についてまとめさせていただくと、高橋しんじ委員からは、本会議において、横山議員の一般質問のうち、一時保護の施設について、定員を上回る状況があると。このような質問があり、その項目もありました。それに関連して、児童相談所を含め、区としての組織的な対応ないし人的対応等についてお聞きしたいということでよろしいですね。"},{"i":312,"speaker":"高橋（し）委員","text":"そうです。具体的に聞けるならば、都児童相談所跡についてどのように、要望しているというと言い方はあれでしょうか、働きかけをしてほしいというふうに他部署もしているかということです。"},{"i":313,"speaker":"つる委員長","text":"分かりました。"},{"i":314,"speaker":"高橋（し）委員","text":"それは大くくりに言ってしまうと、組織的対応、人的対応というのに入るのだと思うのですけれども、それも含めて。"},{"i":315,"speaker":"つる委員長","text":"分かりました。こういう質問でありますので、今、直接の理事者はいらっしゃいませんが、明日の委員会で理事者からのご答弁をいただくというところで調整したいと思います。ほかの委員、それでよろしいですか。\n〔「はい」と呼ぶ者あり〕"},{"i":316,"speaker":"つる委員長","text":"ほかに、その他で何かございますでしょうか。\n〔「なし」と呼ぶ者あり〕"},{"i":317,"speaker":"つる委員長","text":"ないようですので、以上でその他を終了いたします。\n以上で、本日の予定は全て終了しました。\n明日も午前１０時からの開会です。\nこれをもちまして、文教委員会を閉会いたします。\n○午後 ２時０１分閉会"}]});
